/** All translations for zizhitongjian ch.016 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起強圉大淵獻，盡上章困敦，凡十四年。", literal: "From Qianggu Dayuanxian through Shangzhang Kundun; fourteen years in all.", idiomatic: "From Qianggu Dayuanxian through Shangzhang Kundun—fourteen years in all." },
  { zh: "1冬，十月，梁王來朝。", literal: "1. In winter, the tenth month, the King of Liang came to court.", idiomatic: "1. In winter, the tenth month, the King of Liang came to court." },
  { zh: "時上未置太子，與梁王宴飲，從容言曰：「千秋萬歲後傳於王。", literal: "At the time the emperor had not yet installed a crown prince; feasting with the King of Liang, he spoke at ease, saying: \"After a thousand autumns and ten thousand years I shall pass it to you, King.", idiomatic: "The emperor had not yet named a crown prince. Over wine with the King of Liang he said lightly, \"When a thousand autumns and ten thousand years have passed, I shall pass the throne to you, my king." },
  { zh: "」王辭謝，雖知非至言，然心內喜，太后亦然。", literal: "\" The king declined with thanks; though he knew these were not words meant in earnest, inwardly he was pleased, and the empress dowager likewise.", idiomatic: "\" The king declined with thanks. Though he knew these were not words meant in earnest, inwardly he rejoiced—and so did the empress dowager." },
  { zh: "詹事竇嬰引卮酒進上曰：「天下者，高祖之天下，父子相傳，漢之約也，上何以得傳梁王！", literal: "Household intendant Dou Ying raised his cup of wine and advanced to the emperor, saying: \"All under Heaven is Gaozu's all under Heaven; father passes to son—this is Han's covenant. How could Your Majesty pass it to the King of Liang!", idiomatic: "Household intendant Dou Ying raised his cup and stepped forward. \"All under Heaven belongs to Gaozu,\" he said. \"Father passes the realm to son—that is Han's covenant. How could Your Majesty pass it to the King of Liang!" },
  { zh: "」太后由此憎嬰。", literal: "\" From this the empress dowager came to hate Dou Ying.", idiomatic: "\" From that moment the empress dowager hated Dou Ying." },
  { zh: "嬰因病免；", literal: "Dou Ying was dismissed on account of illness;", idiomatic: "Dou Ying was dismissed, pleading illness;" },
  { zh: "太后除嬰門籍，不得朝請。", literal: "the empress dowager removed Dou Ying from the court registry and he could not attend audiences.", idiomatic: "and the empress dowager struck his name from the court registry so he could no longer attend audiences." },
  { zh: "梁王以此益驕。", literal: "The King of Liang for this reason grew still more arrogant.", idiomatic: "The King of Liang grew still more arrogant because of it." },
  { zh: "----2春，正月，乙巳，赦。", literal: "----2 In spring, the first month, on yisi, a pardon.", idiomatic: "----2 In spring, the first month, on the day yisi, a general pardon was proclaimed." },
  { zh: "----3長星出西方。", literal: "----3 A long comet appeared in the west.", idiomatic: "----3 A long-tailed comet appeared in the west." },
  { zh: "----4洛陽東宮災。", literal: "----4 The Eastern Palace at Luoyang caught fire.", idiomatic: "----4 Fire destroyed the Eastern Palace at Luoyang." },
  { zh: "----5初，孝文時，吳太子入見，得侍皇太子飲、博。", literal: "----5 At the outset, in Emperor Wen's time, the heir of Wu came in audience and was permitted to attend the crown prince in drinking and gaming.", idiomatic: "----5 Earlier, in Emperor Wen's reign, the heir of Wu came to court and was allowed to drink and play board games with the crown prince." },
  { zh: "吳太子博爭道，不恭；", literal: "The heir of Wu disputed the board in gaming and was disrespectful;", idiomatic: "During a game the heir of Wu disputed a move and behaved disrespectfully;" },
  { zh: "皇太子引博局提吳太子，殺之。", literal: "the crown prince seized the gaming board and struck the heir of Wu, killing him.", idiomatic: "the crown prince seized the board and struck the heir of Wu, killing him." },
  { zh: "遣其喪歸葬，至吳，吳王慍曰：「天下同宗，死長安即葬長安，何必來葬為！", literal: "They sent the coffin back for burial; when it reached Wu, the King of Wu said angrily: \"All under Heaven share one ancestry—if he died in Chang'an, bury him in Chang'an; why must you come here to bury!", idiomatic: "They sent the body home for burial. When the coffin reached Wu, the King of Wu said in anger, \"We share one ancestry under Heaven. If he died in Chang'an, bury him in Chang'an—why drag him here to bury!" },
  { zh: "」復遣喪之長安葬。", literal: "\" They again sent the coffin to Chang'an for burial.", idiomatic: "\" They sent the coffin back to Chang'an for burial." },
  { zh: "吳王由此稍失籓臣之禮，稱疾不朝。", literal: "The King of Wu for this reason gradually lapsed from a feudal subject's rites and claimed illness and did not attend court.", idiomatic: "From this the King of Wu gradually abandoned a vassal's courtesies, claiming illness and refusing to attend court." },
  { zh: "京師知其以子故，系治、驗問吳使者；", literal: "The capital knew this was on account of his son and detained and interrogated Wu's envoys;", idiomatic: "The capital knew the cause was his son and detained and interrogated Wu's envoys;" },
  { zh: "吳王恐，始有反謀。", literal: "the King of Wu grew afraid and first formed plans of rebellion.", idiomatic: "and the King of Wu, growing afraid, first conceived plans of rebellion." },
  { zh: "後使人為秋請，文帝復問之，使者對曰：「王實不病；", literal: "Later someone was sent on autumn petition; Emperor Wen again questioned him, and the envoy replied: \"The king is in fact not ill;", idiomatic: "Later an envoy came with the autumn petition. Emperor Wen questioned him again, and the envoy answered, \"The king is not ill at all;" },
  { zh: "漢系治使者數輩，吳王恐，以故遂稱病。", literal: "Han has detained several envoys; the King of Wu was afraid and for that reason then claimed illness.", idiomatic: "Han has detained several of our envoys. The King of Wu was afraid, and for that reason he claimed illness." },
  { zh: "夫察見淵中魚不祥，唯上棄前過，與之更始。", literal: "To scrutinize so closely as to see fish in the depths is inauspicious; I pray Your Majesty discard former faults and grant him a fresh start.", idiomatic: "To see fish in a deep pool is inauspicious—too close a scrutiny. I pray Your Majesty discard former faults and grant him a fresh start." },
  { zh: "」於是文帝乃赦吳使者，歸之，而賜吳王幾杖，老，不朝。", literal: "\" Thereupon Emperor Wen pardoned Wu's envoys and sent them back, and bestowed on the King of Wu a staff of rest for old age, exempt from court attendance.", idiomatic: "\" Thereupon Emperor Wen pardoned Wu's envoys and sent them home, and bestowed on the King of Wu a cane of ease in old age, exempting him from court attendance." },
  { zh: "吳得釋其罪，謀亦益解。", literal: "Wu was released from his guilt and the plot also gradually dissolved.", idiomatic: "Wu was released from blame, and the plot gradually dissolved as well." },
  { zh: "然其居國，以銅、鹽故，百姓無賦；", literal: "Yet in his realm, on account of copper and salt, the common people paid no taxes;", idiomatic: "Yet within his realm, because of copper and salt, the common people paid no taxes;" },
  { zh: "卒踐更，輒予平賈；", literal: "when soldiers performed rotation duty, he at once paid fair market price;", idiomatic: "when soldiers performed corvée rotation, he paid them fair market wages;" },
  { zh: "歲時存問茂材，賞賜閭里；", literal: "at year's seasons he inquired after outstanding talent and rewarded village neighborhoods;", idiomatic: "at each season he inquired after outstanding men and rewarded the villages;" },
  { zh: "他郡國吏欲來捕亡人者，公共禁弗予。", literal: "when officials of other commanderies and states wished to come capture fugitives, he publicly forbade and would not yield them.", idiomatic: "when officials from other commanderies and kingdoms came to seize fugitives, he publicly forbade it and would not hand them over." },
  { zh: "如此者四十餘年。", literal: "Thus for more than forty years.", idiomatic: "This went on for more than forty years." },
  { zh: "晁錯數上書言吳過，可削；", literal: "Chao Cuo repeatedly submitted memorials saying Wu's faults could be cut away;", idiomatic: "Chao Cuo repeatedly memorialized that Wu's offenses warranted reduction;" },
  { zh: "文帝寬，不忍罰，以此吳日益橫。", literal: "Emperor Wen was lenient and could not bear to punish; for this Wu daily grew more overbearing.", idiomatic: "Emperor Wen was lenient and could not bear to punish him, and for this Wu grew daily more overbearing." },
  { zh: "及帝即位，錯說上曰：「昔高帝初定天下，昆弟少，諸子弱，大封同姓，齊七十餘城，楚四十餘城，吳五十餘城；", literal: "When the emperor took the throne, Chao Cuo persuaded him, saying: \"Of old when Gaodi first settled all under Heaven, brothers were few and sons weak; he greatly enfeoffed those of the same surname—Qi had more than seventy cities, Chu more than forty, Wu more than fifty;", idiomatic: "When the new emperor took the throne, Chao Cuo urged him: \"When Gaodi first settled the realm, his brothers were few and his sons young. He enfeoffed kinsmen on a vast scale—Qi held more than seventy cities, Chu more than forty, Wu more than fifty;" },
  { zh: "封三庶孽，分天下半。", literal: "he enfeoffed three collateral lines and divided half all under Heaven.", idiomatic: "he enfeoffed three collateral lines and gave them half the realm." },
  { zh: "今吳王前有太子之郤，詐稱病不朝，於古法當誅。", literal: "Now the King of Wu earlier had the matter of the crown prince's grudge, feigned illness and did not attend court—by ancient law he should be executed.", idiomatic: "The King of Wu already bears a grudge over the crown prince's killing of his heir, and he feigned illness to avoid court—by ancient law he should be executed." },
  { zh: "文帝弗忍，因賜幾杖，德至厚，當改過自新，反益驕溢，即山鑄錢，煮海水為鹽，誘天下亡人謀作亂。", literal: "Emperor Wen could not bear it and therefore bestowed the rest-staff—grace reaching utmost depth; he should have changed his faults and renewed himself, but instead grew still more arrogant and excessive, minting coin by the mountains and boiling sea water for salt, luring all under Heaven's fugitives and plotting rebellion.", idiomatic: "Emperor Wen could not bear to punish him and instead bestowed a cane of ease—grace of the deepest kind. He should have mended his ways, but grew only more arrogant: minting coin in the hills, boiling seawater for salt, luring fugitives from across the realm, and plotting rebellion." },
  { zh: "今削之亦反，不削亦反。", literal: "Now if you cut him he will rebel; if you do not cut him he will also rebel.", idiomatic: "Cut his territory and he will rebel; leave it uncut and he will rebel anyway." },
  { zh: "削之，其反亟，禍小；", literal: "If you cut, his rebellion will be urgent but the calamity small;", idiomatic: "If you cut now, his rebellion will come soon but the calamity will be small;" },
  { zh: "不削，反遲，禍大。", literal: "if you do not cut, rebellion will be delayed but the calamity great.", idiomatic: "if you do not cut, rebellion will come late but the calamity will be great." },
  { zh: "」上令公卿、列侯、宗室雜議，莫敢難；", literal: "\" The emperor ordered the high ministers, ranked marquises, and imperial clan to debate together; none dared object;", idiomatic: "\" The emperor ordered the high ministers, ranked marquises, and imperial clan to debate the matter together. None dared object;" },
  { zh: "獨竇嬰爭之，由此與錯有郤。", literal: "only Dou Ying contested it, and from this he had a grudge with Chao Cuo.", idiomatic: "only Dou Ying argued against it, and from this he and Chao Cuo bore a grudge." },
  { zh: "及楚王戊來朝，錯因言：「戊往年為薄太后服，私奸服舍，請誅之。", literal: "When King Wu of Chu came to court, Chao Cuo took occasion to say: \"Wu in a past year for Empress Dowager Bo's mourning privately committed impropriety in the mourning lodge; I request he be executed.", idiomatic: "When King Wu of Chu came to court, Chao Cuo seized the occasion to say, \"In a past year Wu, while mourning Empress Dowager Bo, committed impropriety in the mourning lodge. I ask that he be executed." },
  { zh: "」詔赦，削東海郡。", literal: "\" An edict pardoned him and cut away Donghai commandery.", idiomatic: "\" An edict pardoned him but stripped away Donghai commandery." },
  { zh: "及前年，趙王有罪，削其常山郡；", literal: "And in the year before last, the King of Zhao had guilt and Changshan commandery was cut away;", idiomatic: "The year before last the King of Zhao was found guilty and Changshan commandery was cut away;" },
  { zh: "膠西王卬以賣爵事有奸，削其六縣。", literal: "King Ying of Jiaoxi on account of selling ranks had impropriety and six counties were cut from him.", idiomatic: "King Ying of Jiaoxi was implicated in selling ranks and lost six counties." },
  { zh: "廷臣方議削吳。", literal: "Court ministers were then debating cutting Wu.", idiomatic: "Court ministers were then debating how to reduce Wu." },
  { zh: "吳王恐削地無已，因發謀舉事。", literal: "The King of Wu, fearing the cutting of territory would never end, thereupon launched his plot and raised the affair.", idiomatic: "The King of Wu, fearing his lands would be cut without end, thereupon set his plot in motion." },
  { zh: "念諸侯無足與計者，聞膠西王勇，好兵，諸侯皆畏憚之，於是使中大夫應高口說膠西王曰：「今者主上任用邪臣，聽信讒賊，侵削諸侯，誅罰良重，日以益甚。", literal: "Thinking no feudal lord was fit to plan with, he heard King Ying of Jiaoxi was brave and loved troops and that all feudal lords feared him; he therefore sent Central Grandee Ying Gao to speak and persuade King Ying of Jiaoxi, saying: \"Now the ruler employs wicked ministers, listens to slanderers, invades and cuts feudal lords, punishments and executions very heavy, daily growing worse.", idiomatic: "He judged no other feudal lord fit to plot with, but heard that King Ying of Jiaoxi was brave, loved arms, and was feared by all the princes. He therefore sent Central Grandee Ying Gao to persuade him in person: \"The Son of Heaven now employs wicked ministers, heeds slanderers, strips the feudal lords, and metes out ever heavier punishments day by day." },
  { zh: "語有之曰：『狧糠及米。", literal: "There is a saying: 'When the thorny brush is scraped to the chaff, it reaches the grain.", idiomatic: "There is a saying: 'Scrape the chaff and you reach the grain." },
  { zh: "』吳與膠西，知名諸侯也，一時見察，不得安肆矣。", literal: "' Wu and Jiaoxi are famed feudal lords; once examined together, we cannot rest secure.", idiomatic: "' Wu and Jiaoxi are famed among the princes. Once scrutinized together, neither of us can rest secure." },
  { zh: "吳王身有內疾，不能朝請二十餘年，常患見疑，無以自白，脅肩累足，猶懼不見釋。", literal: "The King of Wu has internal illness and cannot attend court for more than twenty years; he constantly fears being suspected with no means to clear himself, shoulders hunched and feet piled, still afraid of not being released.", idiomatic: "The King of Wu has been too ill to attend court for more than twenty years. He lives in constant fear of suspicion with no way to clear himself—shoulders hunched, feet drawn in—still afraid he will not be spared." },
  { zh: "竊聞大王以爵事有過。", literal: "I have privately heard that Your Majesty had fault in the matter of selling ranks.", idiomatic: "I have heard privately that Your Majesty was faulted in the matter of selling ranks." },
  { zh: "所聞諸侯削地，罪不至此；", literal: "What I hear is that feudal lords' lands cut—the crime did not reach this;", idiomatic: "What I hear is that when feudal lords lose territory, the crime does not warrant this;" },
  { zh: "此恐不止削地而已。", literal: "this I fear is not only cutting territory.", idiomatic: "and I fear this will not stop at cutting territory alone." },
  { zh: "」王曰：「有之。", literal: "\" The king said: \"It is so.", idiomatic: "\" The king said, \"It is so." },
  { zh: "子將奈何？", literal: "What will you do?", idiomatic: "What do you propose?" },
  { zh: "」高曰：「吳王自以與大王同憂，願因時循理，棄軀以除患於天下，意亦可乎？", literal: "\" Gao said: \"The King of Wu considers himself to share Your Majesty's worry; he wishes by the time and reason's course to cast aside his body to remove the affliction from all under Heaven—would that be acceptable?", idiomatic: "\" Gao said, \"The King of Wu believes he shares Your Majesty's peril. He wishes, seizing the moment and following right principle, to cast aside his body and remove this affliction from the realm. Would that be acceptable?" },
  { zh: "」膠西王瞿然駭曰：「寡人何敢如是！", literal: "\" King Ying of Jiaoxi started in alarm and said: \"How dare I do such a thing!", idiomatic: "\" King Ying of Jiaoxi started in alarm. \"How dare I do such a thing!" },
  { zh: "王上雖急，固有死耳，安得不事！", literal: "Though the Son of Heaven is harsh, there is certainly death—how could one not serve!", idiomatic: "However harsh the Son of Heaven may be, death is certain—how could one refuse to serve!" },
  { zh: "」高曰：「御史大夫晁錯，營惑天子，侵奪諸侯，朝廷疾怨，諸侯皆有背叛之意，人事極矣。", literal: "\" Gao said: \"Grandee Secretary Chao Cuo confuses the Son of Heaven and invades and seizes from feudal lords; court and ministers resent with illness, all feudal lords have intent to rebel—human affairs have reached the limit.", idiomatic: "\" Gao said, \"Grandee Secretary Chao Cuo bewilders the Son of Heaven and strips the feudal lords. Court and capital seethe with resentment; every prince harbors thoughts of rebellion. Human affairs have reached their limit." },
  { zh: "彗星出，蝗蟲起，此萬世一時；", literal: "A comet has appeared, locusts have risen—this is an opportunity of ten thousand generations;", idiomatic: "A comet has appeared, locusts have risen—this is a chance that comes once in ten thousand generations;" },
  { zh: "而愁勞，聖人所以起也。", literal: "and worry and toil are why the sage arises.", idiomatic: "and worry and toil are what rouse the sage to act." },
  { zh: "吳王內以晁錯為誅，外從大王后車，方洋天下，所向者降，所指者下，莫敢不服。", literal: "The King of Wu within will take Chao Cuo for execution; without will follow Your Majesty's rear carriage; far and wide across all under Heaven, where he turns all submit, where he points all fall—none dare not submit.", idiomatic: "The King of Wu will execute Chao Cuo within the realm and follow Your Majesty's chariot without. He will sweep across the realm—where he turns, men submit; where he points, cities fall. None will dare refuse." },
  { zh: "大王誠幸而許之一言，則吳王率楚王略函谷關，守滎陽、敖倉之粟，距漢兵，治次舍，須大王。", literal: "If Your Majesty truly deigns to assent with one word, then the King of Wu will lead the King of Chu to seize Hangu Pass, guard the grain at Xingyang and Aocang, resist Han troops, set up lodging, and wait for Your Majesty.", idiomatic: "If Your Majesty will grant a single word of assent, the King of Wu will lead the King of Chu to seize Hangu Pass, hold the grain at Xingyang and Aocang, block Han's armies, and prepare lodging while he awaits Your Majesty." },
  { zh: "大王幸而臨之，則天下可並，兩主分割，不亦可乎！", literal: "If Your Majesty deigns to come, then all under Heaven can be united, two lords dividing it—is that not also acceptable!", idiomatic: "If Your Majesty comes in person, the realm can be united—or two lords can divide it. Would that not serve as well!" },
  { zh: "」王曰：「善！", literal: "\" The king said: \"Good!", idiomatic: "\" The king said, \"Good!" },
  { zh: "」歸，報吳王，吳王猶恐其不果，乃身自為使者，至膠西面約之。", literal: "\" He returned and reported to the King of Wu; the King of Wu still feared it would not succeed and thereupon went in person as envoy to Jiaoxi's border to covenant with him.", idiomatic: "\" He returned and reported to the King of Wu. The King of Wu still feared the plan would fail and went in person as envoy to Jiaoxi's border to seal the covenant." },
  { zh: "膠西群臣或聞王謀，諫曰：「諸侯地不能當漢十二，為叛逆以憂太后，非計也。", literal: "Some of Jiaoxi's ministers heard the king's plot and remonstrated: \"Feudal lords' lands cannot equal one-twelfth of Han; to rebel and worry the empress dowager is not a plan.", idiomatic: "Some of Jiaoxi's ministers heard the king's plot and remonstrated: \"The feudal lords' lands cannot match one-twelfth of Han's. To rebel and grieve the empress dowager is no plan at all." },
  { zh: "今承一帝，尚雲不易；", literal: "Now serving one emperor, it is still said not easy;", idiomatic: "Serving one emperor is already said to be hard enough;" },
  { zh: "假令事成，兩主分爭，患乃益生。", literal: "suppose it succeeds, two lords contend and afflictions will only increase.", idiomatic: "suppose it succeeds—two lords will contend, and troubles will only multiply." },
  { zh: "」王不聽，遂發使約齊、菑川、膠東、濟南，皆許諾。", literal: "\" The king did not listen and thereupon sent envoys to covenant with Qi, Zichuan, Jiaodong, and Jinan; all promised.", idiomatic: "\" The king would not listen. He sent envoys to covenant with Qi, Zichuan, Jiaodong, and Jinan, and all promised." },
  { zh: "初，楚元王好書，與魯申公、穆生、白生俱受《詩》於浮丘伯；", literal: "At the outset, King Yuan of Chu loved books; with Lu's Lord Shen, Mu Sheng, and Bai Sheng together he received the Odes from Fuqiu Bo;", idiomatic: "Earlier, King Yuan of Chu loved learning. With Lord Shen of Lu, Mu Sheng, and Bai Sheng he studied the Odes under Fuqiu Bo;" },
  { zh: "及王楚，以三人為中大夫。", literal: "when he became king of Chu, he made the three men central grandees.", idiomatic: "when he became king of Chu he made all three central grandees." },
  { zh: "穆生不耆酒；", literal: "Mu Sheng did not love wine;", idiomatic: "Mu Sheng did not drink wine;" },
  { zh: "元王每置酒，常為穆生設醴。", literal: "King Yuan each time he set out wine always set out sweet wine for Mu Sheng.", idiomatic: "whenever King Yuan held a feast he always set out sweet wine for Mu Sheng." },
  { zh: "及子夷王、孫王戊即位，常設，後乃忘設焉。", literal: "When his son King Yi and grandson King Wu took the throne, it was routinely set, but later they forgot to set it.", idiomatic: "When his son King Yi and grandson King Wu succeeded, the custom held for a time, but later they forgot to set it out." },
  { zh: "穆生退，曰：「可以逝矣！", literal: "Mu Sheng withdrew, saying: \"I may depart!", idiomatic: "Mu Sheng withdrew, saying, \"It is time to go!" },
  { zh: "醴酒不設，王之意怠；", literal: "Sweet wine not set—the king's intent is slack;", idiomatic: "No sweet wine set out—the king's regard has slackened;" },
  { zh: "不去，楚人將鉗我於市。", literal: "if I do not leave, the men of Chu will clamp me in the market.", idiomatic: "if I do not leave, the men of Chu will clamp me in irons at the market." },
  { zh: "」遂稱疾臥。", literal: "\" He thereupon claimed illness and kept to bed.", idiomatic: "\" He thereupon claimed illness and kept to his bed." },
  { zh: "申公、白生強起之，曰：「獨不念先王之德與！", literal: "Lord Shen and Bai Sheng forcibly roused him, saying: \"Will you alone not recall the former king's virtue!", idiomatic: "Lord Shen and Bai Sheng tried to rouse him by force, saying, \"Will you alone forget the former king's kindness!" },
  { zh: "今王一旦失小禮，何足至此！", literal: "Now the king once lost a small courtesy—how does it reach this!", idiomatic: "The present king missed one small courtesy—how can that justify this!" },
  { zh: "」穆生曰：「《易》稱：『知幾其神乎！", literal: "\" Mu Sheng said: \"The Changes says: 'To know the subtle—is it not spiritlike!", idiomatic: "\" Mu Sheng said, \"The Changes says, 'To know the subtle—is that not spiritlike!" },
  { zh: "幾者，動之微，吉兇之先見者也。", literal: "The subtle is the incipient of movement, fortune and calamity seen beforehand.", idiomatic: "The subtle is the first stir of movement, fortune and calamity seen before they arrive." },
  { zh: "君子見幾而作，不俟終日。", literal: "The noble person seeing the subtle acts; he does not wait out the day.", idiomatic: "The noble person sees the subtle and acts; he does not wait out the day." },
  { zh: "』先王之所以禮吾三人者，為道存也。", literal: "' The former king's reason for honoring us three was that the Way endured.", idiomatic: "' The former king honored us three because the Way still endured." },
  { zh: "今而忽之，是忘道也。", literal: "Now to slight us—this is forgetting the Way.", idiomatic: "To slight us now is to forget the Way." },
  { zh: "忘道之人，胡可與久處，豈為區區之禮哉！", literal: "One who forgets the Way—how can one dwell long with him; how is it for a trifling courtesy!", idiomatic: "How can one dwell long with one who has forgotten the Way—for a trifling courtesy!" },
  { zh: "」遂謝病去。", literal: "\" He thereupon took leave for illness and departed.", idiomatic: "\" He took leave on grounds of illness and departed." },
  { zh: "申公、白生獨留。", literal: "Lord Shen and Bai Sheng alone remained.", idiomatic: "Lord Shen and Bai Sheng alone remained." },
  { zh: "王戊稍淫暴，太傅韋孟作詩諷諫，不聽，亦去，居於鄒。", literal: "King Wu gradually grew licentious and violent; Grand Tutor Wei Meng composed verse to admonish indirectly; he was not heeded and also left, dwelling in Zou.", idiomatic: "King Wu grew gradually licentious and violent. Grand Tutor Wei Meng wrote verse to admonish him indirectly; when the king would not listen, he too departed and lived in Zou." },
  { zh: "戊因坐削地事，遂與吳通謀。", literal: "Wu on account of the matter of cut territory thereupon communicated plots with Wu.", idiomatic: "Wu, implicated in the reduction of his territory, thereupon joined plots with the King of Wu." },
  { zh: "申公、白生諫戊，戊胥靡之，衣之赭衣，使雅舂於市。", literal: "Lord Shen and Bai Sheng remonstrated with Wu; Wu made them bondsmen, clothed them in ochre garments, and made them pound grain with the mortar at the market.", idiomatic: "Lord Shen and Bai Sheng remonstrated with Wu. Wu made them convict bondsmen, clothed them in ochre, and set them pounding grain with the mortar in the market." },
  { zh: "休侯富使人諫王。", literal: "Marquis Xiu Fu sent someone to remonstrate with the king.", idiomatic: "Marquis Xiu Fu sent someone to remonstrate with the king." },
  { zh: "王曰：「季父不吾與，我起，先取季父矣！", literal: "The king said: \"My uncle does not stand with me; when I rise, I will take my uncle first!", idiomatic: "The king said, \"My uncle will not stand with me. When I rise, I will take my uncle first!" },
  { zh: "」休侯懼，乃與母太夫人奔京師。", literal: "\" Marquis Xiu was afraid and thereupon with his mother the great lady fled to the capital.", idiomatic: "\" Marquis Xiu was afraid and fled with his mother the great lady to the capital." },
  { zh: "及削吳會稽、豫章郡書至，吳王遂先起兵，誅漢吏二千石以下；", literal: "When the document cutting Wu's Kuaiji and Yuzhang commanderies arrived, the King of Wu thereupon first raised troops and executed Han officials of two thousand piculs and below;", idiomatic: "When the edict cutting Kuaiji and Yuzhang from Wu arrived, the King of Wu was first to raise troops and execute Han officials of two thousand piculs rank and below;" },
  { zh: "膠西、膠東、菑川、濟南、楚、趙亦皆反。", literal: "Jiaoxi, Jiaodong, Zichuan, Jinan, Chu, and Zhao also all rebelled.", idiomatic: "Jiaoxi, Jiaodong, Zichuan, Jinan, Chu, and Zhao rebelled as well." },
  { zh: "楚相張尚、太傅趙夷吾諫王戊，戊殺尚、夷吾。", literal: "Chu's chancellor Zhang Shang and grand tutor Zhao Yiwu remonstrated with King Wu; Wu killed Shang and Yiwu.", idiomatic: "Chu's chancellor Zhang Shang and grand tutor Zhao Yiwu remonstrated with King Wu; Wu killed them both." },
  { zh: "趙相建德、內史王悍諫王遂，遂燒殺建德、悍。", literal: "Zhao's chancellor Jian De and internuncius Wang Han remonstrated with King Sui; Sui burned them alive and killed Jian De and Han.", idiomatic: "Zhao's chancellor Jian De and internuncius Wang Han remonstrated with King Sui; Sui burned them alive." },
  { zh: "齊王後悔，背約城守。", literal: "The King of Qi repented, broke the agreement, and held the city in defense.", idiomatic: "The King of Qi repented, broke the agreement, and defended the city." },
  { zh: "濟北王城壞未完，其郎中令劫守，王不得發兵。", literal: "The King of Jibei's city walls were breached and not yet repaired; his Director of the Secretariat seized the garrison, and the king could not dispatch troops.", idiomatic: "The King of Jibei's walls were breached and not yet repaired; his Director of the Secretariat seized the garrison, and the king could not raise troops." },
  { zh: "膠西王、膠東王為渠率，與菑川、濟南共攻齊，圍臨菑。", literal: "The Kings of Jiaoxi and Jiaodong served as ringleaders, and together with Zichuan and Jinan attacked Qi and besieged Linzi.", idiomatic: "The Kings of Jiaoxi and Jiaodong led the attack, and together with Zichuan and Jinan they assaulted Qi and besieged Linzi." },
  { zh: "趙王遂發兵住其西界，欲待吳、楚俱進，北使匈奴與連兵。", literal: "The King of Zhao thereupon raised troops and halted on its western border, wishing to wait until Wu and Chu advanced together and to send north to the Xiongnu to join forces.", idiomatic: "The King of Zhao thereupon raised troops and held the western border, intending to wait for Wu and Chu to advance together and to link arms with the Xiongnu in the north." },
  { zh: "吳王悉其士卒，下令國中曰：「寡人年六十二，身自將；", literal: "The King of Wu mustered all his troops and ordered within the state, saying: \"I am sixty-two years old and shall command in person;", idiomatic: "The King of Wu mustered all his troops and proclaimed throughout the state, \"I am sixty-two years old and shall take command in person;" },
  { zh: "少子年十四，亦為士卒先。", literal: "My youngest son is fourteen and shall also lead the troops as vanguard.", idiomatic: "My youngest son is fourteen and shall also lead the troops as vanguard." },
  { zh: "諸年上與寡人同，下與少子等，皆發。", literal: "All from my age upward and from my youngest son's age downward—everyone shall be mobilized.", idiomatic: "All from my age upward and from my youngest son's age downward shall be mobilized." },
  { zh: "」凡二十餘萬人。", literal: "\" In all there were more than two hundred thousand men.", idiomatic: "\" In all there were more than two hundred thousand men." },
  { zh: "南使閩、東越，閩、東越亦發兵從。", literal: "He sent south to Min and Dongyue, and Min and Dongyue also raised troops to follow.", idiomatic: "He sent south to Min and Dongyue, and they too raised troops to follow." },
  { zh: "吳王起兵於廣陵，西涉淮，因並楚兵，發使遺諸侯書，罪狀晁錯，欲合兵誅之。", literal: "The King of Wu raised troops at Guangling, crossed west over the Huai, and thereupon merged Chu forces; he sent envoys with letters to the feudal lords, listing Chao Cuo's crimes, wishing to unite armies and execute him.", idiomatic: "The King of Wu raised troops at Guangling, crossed the Huai westward, merged Chu forces, and sent envoys with letters to the feudal lords listing Chao Cuo's crimes, intending to unite armies and kill him." },
  { zh: "吳、楚共攻梁，破棘壁，殺數萬人；", literal: "Wu and Chu together attacked Liang, broke through Jibi, and killed tens of thousands;", idiomatic: "Wu and Chu together attacked Liang, broke through Jibi, and killed tens of thousands;" },
  { zh: "乘勝而前，銳甚。", literal: "pressing the victory forward, they were very sharp.", idiomatic: "pressing their victory forward, they were very fierce." },
  { zh: "梁孝王遣將軍擊之，又敗梁兩軍，士卒皆還走。", literal: "King Xiao of Liang sent generals to strike them, but they again defeated Liang's two armies, and the soldiers all fled back.", idiomatic: "King Xiao of Liang sent generals against them, but they again defeated Liang's two armies, and the troops all fled." },
  { zh: "梁王城守睢陽。", literal: "The King of Liang held Suiyang in defense.", idiomatic: "The King of Liang defended Suiyang." },
  { zh: "初，文帝且崩，戒太子曰：「即有緩急，周亞夫真可任將兵。", literal: "At the outset, when Emperor Wen was about to die, he warned the crown prince, saying: \"If there should be urgency, Zhou Yafu truly can be entrusted with commanding troops.", idiomatic: "Earlier, when Emperor Wen was about to die, he warned the crown prince, \"If there is an emergency, Zhou Yafu truly can be entrusted with command of the army." },
  { zh: "」及七國反書聞，上乃拜中尉周亞夫為太尉，將三十六將軍往擊吳、楚，遣曲周侯酈寄擊趙，將軍欒布擊齊；", literal: "\" When word of the Seven States' rebellion arrived, the emperor thereupon appointed Commandant of the Guards Zhou Yafu Grand Commandant, to lead thirty-six generals to strike Wu and Chu; he sent Marquis Ji of Quzhou Li Ji to strike Zhao and General Luan Bu to strike Qi;", idiomatic: "\" When word of the Seven States' rebellion arrived, the emperor appointed Commandant of the Guards Zhou Yafu Grand Commandant and sent him with thirty-six generals against Wu and Chu; he sent Marquis Ji of Quzhou Li Ji against Zhao and General Luan Bu against Qi;" },
  { zh: "復召竇嬰，拜為大將軍，使屯滎陽監齊、趙兵。", literal: "He again summoned Dou Ying, appointed him Grand General, and had him garrison at Xingyang to oversee Qi and Zhao forces.", idiomatic: "He again summoned Dou Ying, appointed him Grand General, and stationed him at Xingyang to oversee the Qi and Zhao armies." },
  { zh: "初，晁錯所更令三十章，諸侯讙嘩。", literal: "At the outset, the thirty chapters of ordinances that Chao Cuo had revised made the feudal lords clamor in uproar.", idiomatic: "Earlier, the thirty chapters of ordinances that Chao Cuo had revised threw the feudal lords into an uproar." },
  { zh: "錯父聞之，從穎川來，謂錯曰：「上初即位，公為政用事，侵削諸侯，疏人骨肉，口語多怨，公何為也？", literal: "Cuo's father heard of it, came from Yingchuan, and said to Cuo: \"The emperor has just taken the throne; you hold power in government, encroach upon and pare the feudal lords, estrange men of flesh and bone, and many murmur in resentment—what are you doing?", idiomatic: "Cuo's father heard of it, came from Yingchuan, and said to Cuo, \"The emperor has just taken the throne; you hold power, encroach upon and pare the feudal lords, estrange kin, and many murmur in resentment—what are you doing?" },
  { zh: "」錯曰：「固也。", literal: "\" Cuo said: \"Indeed.", idiomatic: "\" Cuo said, \"Indeed." },
  { zh: "不如此，天子不尊，宗廟不安。", literal: "If it were not so, the Son of Heaven would not be honored and the ancestral temple would not be secure.", idiomatic: "If it were not so, the Son of Heaven would not be honored and the ancestral temple would not be secure." },
  { zh: "」父曰：「劉氏安矣而晁氏危，吾去公歸矣！", literal: "\" His father said: \"The Liu clan will be secure but the Chao clan will be in peril—I leave you and return home!", idiomatic: "\" His father said, \"The Liu clan will be secure but the Chao clan will be in peril—I leave you and go home!" },
  { zh: "」遂飲藥死，曰：「吾不忍見禍逮身！", literal: "\" Thereupon he drank poison and died, saying: \"I cannot bear to see disaster reach my person!", idiomatic: "\" Thereupon he drank poison and died, saying, \"I cannot bear to see disaster reach me!" },
  { zh: "」後十餘日，吳、楚七國俱反，以誅錯為名。", literal: "\" More than ten days later, Wu, Chu, and the Seven States all rebelled, taking the execution of Cuo as their pretext.", idiomatic: "\" More than ten days later, Wu, Chu, and the Seven States all rebelled, taking the execution of Cuo as their pretext." },
  { zh: "上與錯議出軍事，錯欲令上自將兵而身居守；", literal: "The emperor discussed military affairs with Cuo; Cuo wished to have the emperor lead the army in person while he himself remained to guard.", idiomatic: "The emperor discussed military affairs with Cuo; Cuo wished to have the emperor lead the army in person while he himself remained behind to guard the capital;" },
  { zh: "又言：「徐、僮之旁吳所未下者，可以予吳。", literal: "He also said: \"The lands beside Xu and Tong that Wu has not yet taken may be granted to Wu.", idiomatic: "he also said, \"The lands beside Xu and Tong that Wu has not yet taken may be granted to Wu." },
  { zh: "」錯素與吳相袁盎不善，錯所居坐，盎輒避；", literal: "\" Cuo had long been on bad terms with Wu's chancellor Yuan Ang; wherever Cuo sat, Ang would avoid it;", idiomatic: "\" Cuo had long been on bad terms with Wu's chancellor Yuan Ang; wherever Cuo sat, Ang would avoid it;" },
  { zh: "盎所居坐，錯亦避；", literal: "wherever Ang sat, Cuo also avoided it;", idiomatic: "wherever Ang sat, Cuo also avoided it;" },
  { zh: "兩人未嘗同堂語。", literal: "the two had never spoken in the same hall.", idiomatic: "the two had never spoken in the same hall." },
  { zh: "及錯為御史大夫，使吏按盎受吳王財物，抵罪；", literal: "When Cuo became Grand Secretary, he sent officials to investigate Ang for receiving goods from the King of Wu and convicted him;", idiomatic: "When Cuo became Grand Secretary, he sent officials to investigate Ang for receiving goods from the King of Wu and convicted him;" },
  { zh: "詔赦以為庶人。", literal: "an edict pardoned him and made him a commoner.", idiomatic: "an edict pardoned him and reduced him to commoner status." },
  { zh: "吳、楚反，錯謂丞、史曰：「袁盎多受吳王金錢，專為蔽匿，言不反；", literal: "When Wu and Chu rebelled, Cuo said to the aides and clerks: \"Yuan Ang received much gold from the King of Wu, deliberately concealed it, and said they would not rebel;", idiomatic: "When Wu and Chu rebelled, Cuo said to the aides and clerks, \"Yuan Ang received much gold from the King of Wu, deliberately concealed it, and said they would not rebel;" },
  { zh: "今果反，欲請治盎，宜知其計謀。", literal: "now they have indeed rebelled—I wish to request that Ang be prosecuted; he ought to know their plans.", idiomatic: "now they have indeed rebelled—I wish to prosecute Ang; he ought to know their plans." },
  { zh: "」丞、史曰：「事未發，治之有絕；", literal: "\" The aides and clerks said: \"Before the affair broke out, prosecuting him would have cut off relations;", idiomatic: "\" The aides and clerks said, \"Before the affair broke out, prosecuting him would have cut off relations;" },
  { zh: "今兵西向，治之何益！", literal: "now the armies face west—what good is prosecuting him!", idiomatic: "now the armies face west—what good is prosecuting him!" },
  { zh: "且盎不宜有謀。", literal: "Moreover Ang is not likely to have plotted.", idiomatic: "Moreover Ang is unlikely to have plotted." },
  { zh: "」錯猶與未決。", literal: "\" Cuo still hesitated and had not decided.", idiomatic: "\" Cuo still hesitated and had not decided." },
  { zh: "人有告盎，盎恐，夜見竇嬰，為言吳所以反，願至前，口對狀。", literal: "Someone informed Ang; Ang was afraid and by night visited Dou Ying, explaining why Wu had rebelled and wishing to go before the throne and answer face to face.", idiomatic: "Someone informed Ang; Ang was afraid and visited Dou Ying by night, explained why Wu had rebelled, and asked to go before the throne and answer in person." },
  { zh: "嬰入言，上乃召盎。", literal: "Ying entered and spoke; the emperor thereupon summoned Ang.", idiomatic: "Ying reported this, and the emperor summoned Ang." },
  { zh: "盎入見，上方與錯調兵食。", literal: "Ang entered to audience; the emperor was just then with Cuo arranging troops and provisions.", idiomatic: "Ang entered to audience; the emperor was just then with Cuo arranging troops and provisions." },
  { zh: "上問盎：「今吳、楚反，於公意何如？", literal: "The emperor asked Ang: \"Now that Wu and Chu have rebelled, what is your view?", idiomatic: "The emperor asked Ang, \"Now that Wu and Chu have rebelled, what is your view?" },
  { zh: "」對曰：「不足憂也！", literal: "\" He replied: \"Nothing to worry about!", idiomatic: "\" He replied, \"Nothing to worry about!" },
  { zh: "」上曰：「吳王即山鑄錢，煮海為鹽，誘天豪傑；", literal: "\" The emperor said: \"The King of Wu coins money from his mountains, boils the sea for salt, and lures heaven's great heroes;", idiomatic: "\" The emperor said, \"The King of Wu coins money from his mountains, boils the sea for salt, and lures the realm's great heroes;" },
  { zh: "白頭舉事、此其計不百全，豈發乎！", literal: "he raises the affair with white hair—this plan is not a hundred parts secure; how could he have launched it!", idiomatic: "he raises the affair in his old age—this plan is not fully secure; how could he have launched it!" },
  { zh: "何以言其無能為也？", literal: "Why do you say he cannot accomplish anything?", idiomatic: "Why do you say he cannot accomplish anything?" },
  { zh: "」對曰：「吳銅鹽之利則有之，安得豪傑而誘之！", literal: "\" He replied: \"Wu has the profit of copper and salt, but how could there be heroes to lure!", idiomatic: "\" He replied, \"Wu has the profit of copper and salt, but where are the heroes to lure!" },
  { zh: "誠令吳得豪傑，亦且輔而為誼，不反矣。", literal: "If Wu truly obtained heroes, they would also assist him in righteousness and would not rebel.", idiomatic: "If Wu truly obtained heroes, they would assist him in loyalty and would not rebel." },
  { zh: "吳所誘皆亡賴子弟、亡命、鑄錢奸人，故相誘以亂」錯曰：「盎策之善。", literal: "Those whom Wu lures are all worthless scions, fugitives, and coiners and villains—therefore they lure one another to rebellion.\" Cuo said: \"Ang's assessment is good.", idiomatic: "Those whom Wu lures are all worthless scions, fugitives, and coiners and villains—therefore they lure one another to rebellion.\" Cuo said, \"Ang's assessment is good." },
  { zh: "」上曰：「計安出？", literal: "\" The emperor said: \"Where does the plan come from?", idiomatic: "\" The emperor said, \"Where does the plan come from?" },
  { zh: "」盎對曰：「願屏左右。", literal: "\" Ang replied: \"I wish to dismiss those at hand.", idiomatic: "\" Ang replied, \"I wish to dismiss those at hand." },
  { zh: "」上屏人，獨錯在。", literal: "\" The emperor dismissed the attendants; only Cuo remained.", idiomatic: "\" The emperor dismissed the attendants; only Cuo remained." },
  { zh: "盎曰：「臣所言，人臣不得知。", literal: "Ang said: \"What your servant will say must not be known to other ministers.", idiomatic: "Ang said, \"What your servant will say must not be known to other ministers." },
  { zh: "」乃屏錯。", literal: "\" He then had Cuo dismissed.", idiomatic: "\" He then had Cuo dismissed." },
  { zh: "錯趨避東廂，甚恨。", literal: "Cuo hurried to avoid him in the east wing, full of hatred.", idiomatic: "Cuo hurried off to the east wing, full of hatred." },
  { zh: "上卒問盎，對曰：「吳、楚相遺書，言高皇帝王子弟各有分地，今賊臣晁錯擅適諸侯，削奪之地，以故反，欲西共誅錯，復故地而罷。", literal: "The emperor at last questioned Ang; he replied: \"Wu and Chu sent each other letters saying that Emperor Gao's imperial sons and younger brothers each had allotted lands, but now the traitor minister Chao Cuo on his own authority punished the feudal lords and seized their lands—therefore they rebel, wishing to march west together to execute Cuo, restore their old lands, and then disband.", idiomatic: "The emperor at last questioned Ang; he replied, \"Wu and Chu sent each other letters saying that Emperor Gao's imperial sons and younger brothers each had allotted lands, but now the traitor minister Chao Cuo on his own authority punished the feudal lords and seized their lands—therefore they rebel, wishing to march west together to execute Cuo, restore their old lands, and then disband." },
  { zh: "方今計獨有斬錯，發使赦吳、楚七國，復其故地，則兵可毋血刃而俱罷。", literal: "At present the plan is solely to behead Cuo, send envoys to pardon Wu, Chu, and the Seven States, and restore their old lands—then the armies can all disband without a blade being bloodied.", idiomatic: "At present the only plan is to behead Cuo, send envoys to pardon Wu, Chu, and the Seven States, and restore their old lands—then the armies can all disband without bloodshed." },
  { zh: "」於是上默然良久，曰：「顧誠何如？", literal: "\" Thereupon the emperor was silent a long while and said: \"But if it is truly so?", idiomatic: "\" Thereupon the emperor was silent a long while and said, \"But if it is truly so?" },
  { zh: "吾不愛一人以謝天下。", literal: "I do not begrudge one man to appease all under Heaven.", idiomatic: "I do not begrudge one man to appease all under Heaven." },
  { zh: "」盎曰：「愚計出此，唯上孰計之！", literal: "\" Ang said: \"This foolish plan comes to this—may Your Majesty weigh it carefully!", idiomatic: "\" Ang said, \"This foolish plan comes to this—may Your Majesty weigh it carefully!" },
  { zh: "」乃拜盎為太常，密裝治行。", literal: "\" He thereupon appointed Ang Grand Master of Ceremonies and secretly prepared his journey.", idiomatic: "\" He thereupon appointed Ang Grand Master of Ceremonies and secretly prepared his journey." },
  { zh: "後十餘日，上令丞相青、中尉嘉、廷尉歐劾奏錯：「不稱主上德信，欲疏群臣、百姓，又欲以城邑予吳，無臣子禮，大逆無道。", literal: "More than ten days later, the emperor ordered Chancellor Qing, Commandant of the Guards Jia, and Commandant of Justice Ou to impeach and memorialize against Cuo: \"He does not proclaim the ruler's virtue and trustworthiness, wishes to estrange ministers and the people, and also wishes to grant cities to Wu—lacking the rites of minister and son, he is greatly rebellious and without the Way.", idiomatic: "More than ten days later, the emperor ordered Chancellor Qing, Commandant of the Guards Jia, and Commandant of Justice Ou to impeach Cuo: \"He does not proclaim the ruler's virtue and trustworthiness, wishes to estrange ministers and the people, and also wishes to grant cities to Wu—lacking the rites of minister and son, he is greatly rebellious and without the Way." },
  { zh: "錯當要斬，父母、妻子、同產無少長皆棄市。", literal: "Cuo should be decapitated at the waist; parents, wife, children, and siblings of the same womb, none young or old, should all be executed in the marketplace.", idiomatic: "Cuo should be decapitated at the waist; parents, wife, children, and siblings, none young or old, should all be executed in the marketplace." },
  { zh: "」制曰：「可。", literal: "\" The rescript said: \"Approved.", idiomatic: "\" The rescript said, \"Approved." },
  { zh: "」錯殊不知。", literal: "\" Cuo knew nothing of it.", idiomatic: "\" Cuo knew nothing of it." },
  { zh: "壬子，上使中尉召錯，紿載行市，錯衣朝衣斬東市。", literal: "On renzi, the emperor sent the Commandant of the Guards to summon Cuo, deceived him into a carriage, and paraded him through the market; Cuo, in court robes, was beheaded in the eastern market.", idiomatic: "On renzi, the emperor sent the Commandant of the Guards to summon Cuo, tricked him into a carriage, and paraded him through the market; Cuo, in court robes, was beheaded in the eastern market." },
  { zh: "上乃使袁盎與吳王弟子宗正德侯通使吳。", literal: "The emperor then sent Yuan Ang and the King of Wu's younger kinsman, Director of the Imperial Clan De Marquis Tong, as envoys to Wu.", idiomatic: "The emperor then sent Yuan Ang and the King of Wu's younger kinsman, Director of the Imperial Clan De Marquis Tong, as envoys to Wu." },
  { zh: "謁者僕射鄧公為校尉，上書言軍事，見上，上問曰：「道軍所來，聞晁錯死，吳、楚罷不？", literal: "Master of Ceremonies Deng Gong served as colonel; he submitted a memorial on military affairs, saw the emperor, and the emperor asked: \"Coming from the army's route, I have heard Chao Cuo is dead—have Wu and Chu disbanded?", idiomatic: "Master of Ceremonies Deng Gong served as colonel; he submitted a memorial on military affairs and saw the emperor, who asked, \"Coming from the army's route, I have heard Chao Cuo is dead—have Wu and Chu disbanded?" },
  { zh: "」鄧公曰：「吳為反數十歲矣；", literal: "\" Deng Gong said: \"Wu has been preparing rebellion for decades;", idiomatic: "\" Deng Gong said, \"Wu has been preparing rebellion for decades;" },
  { zh: "發怒削地，以誅錯為名，其意不在錯也。", literal: "angered by the paring of their lands, they take the execution of Cuo as their pretext—their intent is not on Cuo.", idiomatic: "angered by the paring of their lands, they take the execution of Cuo as their pretext—their intent is not on Cuo." },
  { zh: "且臣恐天下之士拑口不敢復言矣。", literal: "Moreover your servant fears that gentlemen throughout the realm will clamp their mouths shut and not dare speak again.", idiomatic: "Moreover your servant fears that gentlemen throughout the realm will clamp their mouths shut and not dare speak again." },
  { zh: "」上曰：「何哉？", literal: "\" The emperor said: \"How so?", idiomatic: "\" The emperor said, \"How so?" },
  { zh: "」鄧公曰：「夫晁錯患諸侯強大不可制，故請削之以尊京師，萬世之利也。", literal: "\" Deng Gong said: \"Chao Cuo feared that the feudal lords were strong and could not be controlled, and therefore requested to pare them to honor the capital region—benefit for ten thousand generations.", idiomatic: "\" Deng Gong said, \"Chao Cuo feared that the feudal lords were strong and could not be controlled, and therefore requested to pare them to honor the capital—a benefit for ten thousand generations." },
  { zh: "計畫始行，卒受大戮。", literal: "The plan had barely begun when he suddenly suffered great execution.", idiomatic: "The plan had barely begun when he suddenly suffered execution." },
  { zh: "內杜忠臣之口，外為諸侯報仇，臣竊為陛下不取也。", literal: "Within, the mouths of loyal ministers are stopped; without, revenge is wrought for the feudal lords—your servant ventures to think Your Majesty should not have taken this course.", idiomatic: "Within, the mouths of loyal ministers are stopped; without, revenge is wrought for the feudal lords—your servant ventures to think Your Majesty should not have taken this course." },
  { zh: "」於是帝喟然長息曰：「公言善，吾亦恨之！", literal: "\" Thereupon the emperor sighed long and said: \"Your words are good—I too regret it!", idiomatic: "\" Thereupon the emperor sighed long and said, \"Your words are good—I too regret it!" },
  { zh: "袁盎、劉通至吳，吳、楚兵已攻梁壁矣。", literal: "Yuan Ang and Liu Tong reached Wu; Wu and Chu troops had already attacked Liang's walls.", idiomatic: "Yuan Ang and Liu Tong reached Wu; Wu and Chu troops had already attacked Liang's walls." },
  { zh: "宗正以親故，先入見，諭吳王，令拜受詔。", literal: "The Director of the Imperial Clan, by reason of kinship, entered first to audience, instructed the King of Wu, and ordered him to bow and receive the edict.", idiomatic: "The Director of the Imperial Clan, by reason of kinship, entered first, instructed the King of Wu, and ordered him to bow and receive the edict." },
  { zh: "吳王聞袁盎來，知其欲說，笑而應曰：「我已為東帝，尚誰拜！", literal: "The King of Wu heard Yuan Ang had come, knew he wished to persuade him, laughed and replied: \"I am already Eastern Emperor—whom else should I bow to!", idiomatic: "The King of Wu heard Yuan Ang had come, knew he wished to persuade him, laughed and replied, \"I am already Eastern Emperor—whom else should I bow to!" },
  { zh: "」不肯見盎，而留軍中，欲劫使將；", literal: "\" He refused to see Ang but detained him in the army, wishing to coerce him into commanding;", idiomatic: "\" He refused to see Ang but detained him in the army, wishing to coerce him into taking command;" },
  { zh: "盎不肯，使人圍守，且殺之。", literal: "Ang refused; they sent men to surround and guard him and were about to kill him.", idiomatic: "Ang refused; they sent men to surround and guard him and were about to kill him." },
  { zh: "盎得間，脫亡歸報。", literal: "Ang found an opening, escaped, and returned to report.", idiomatic: "Ang found an opening, escaped, and returned to report." },
  { zh: "太尉亞夫言於上曰：「楚兵剽輕，難與爭鋒，願以梁委之，絕其食道，乃可制也。", literal: "Grand Commandant Yafu spoke to the emperor, saying: \"Chu troops are swift and light—hard to contend with at the spearhead; I wish to yield Liang to them, cut off their supply routes, and only then can they be controlled.", idiomatic: "Grand Commandant Yafu spoke to the emperor, saying, \"Chu troops are swift and light—hard to meet head-on; I wish to yield Liang to them, cut off their supply routes, and only then can they be controlled." },
  { zh: "」上許之。", literal: "\" The emperor approved.", idiomatic: "\" The emperor approved." },
  { zh: "亞夫乘六乘傳，將會兵滎陽。", literal: "Yafu rode the six-relay post and was about to assemble troops at Xingyang.", idiomatic: "Yafu took the six-relay post and was about to assemble troops at Xingyang." },
  { zh: "發至霸上，趙涉庶說亞夫曰：「吳王素富，懷輯死士久矣。", literal: "When he set out and reached Bashang, Zhao She the commoner advised Yafu, saying: \"The King of Wu has long been rich and for years has cherished and gathered men who would die for him.", idiomatic: "When he set out and reached Bashang, Zhao She the commoner advised Yafu, saying, \"The King of Wu has long been rich and for years has gathered men who would die for him." },
  { zh: "此知將軍且行，必置間人於殽、澠厄狹之間；", literal: "He knows the general is about to march and is sure to place spies in the narrow passes of Yao and Mian;", idiomatic: "He knows the general is about to march and is sure to place spies in the narrow passes of Yao and Mian;" },
  { zh: "且兵事上神密，將軍何不從此右去，走藍田，出武關，抵洛陽！", literal: "moreover military affairs above all require secrecy—why does the general not turn right from here, hurry through Lantian, exit Wu Pass, and reach Luoyang!", idiomatic: "moreover military affairs above all require secrecy—why does the general not turn right from here, hurry through Lantian, exit Wu Pass, and reach Luoyang!" },
  { zh: "間不過差一二日，直入武庫，擊鳴鼓。", literal: "The delay would be no more than a day or two off; enter straight into the Arsenal and strike the sounding drum.", idiomatic: "The delay would be no more than a day or two; enter straight into the Arsenal and strike the sounding drum." },
  { zh: "諸侯聞之，以為將軍從天而下也。", literal: "The feudal lords hearing it would think the general had descended from Heaven.", idiomatic: "The feudal lords hearing it would think the general had descended from Heaven." },
  { zh: "」太尉如其計，至洛陽，喜曰：「七國反，吾乘傳至此，不自意全。", literal: "\" The Grand Commandant followed his plan; when he reached Luoyang he rejoiced, saying: \"The Seven States rebelled—I rode the relay post to here and did not expect to arrive whole.", idiomatic: "\" The Grand Commandant followed his plan; when he reached Luoyang he rejoiced, saying, \"The Seven States rebelled—I rode the relay post here and did not expect to arrive safe." },
  { zh: "今吾據滎陽，滎陽以東，無足憂者。", literal: "Now that I hold Xingyang, east of Xingyang there is nothing to worry about.", idiomatic: "Now that I hold Xingyang, east of Xingyang there is nothing to worry about." },
  { zh: "」使吏搜殽、澠間，果得吳伏兵。", literal: "\" He sent officials to search between Yao and Mian and indeed found Wu's ambush troops.", idiomatic: "\" He sent officials to search between Yao and Mian and indeed found Wu's ambush troops." },
  { zh: "乃請趙涉為護軍。", literal: "He thereupon requested Zhao She as Protector of the Army.", idiomatic: "He thereupon requested Zhao She as Protector of the Army." },
  { zh: "太尉引兵東北走昌邑。", literal: "The Grand Commandant led his army northeast toward Changyi.", idiomatic: "The Grand Commandant led his army northeast toward Changyi." },
  { zh: "吳攻梁急，梁數使使條侯求救，條侯不許。", literal: "Wu pressed the attack on Liang hard; Liang repeatedly sent envoys to Marquis of Tiao begging rescue, and Marquis of Tiao would not agree.", idiomatic: "Wu pressed the attack on Liang hard; Liang repeatedly sent envoys to Marquis of Tiao begging rescue, and Marquis of Tiao would not agree." },
  { zh: "又使使訴條侯於上。", literal: "He again sent envoys to appeal against Marquis of Tiao to the emperor.", idiomatic: "He again sent envoys to appeal to the emperor against Marquis of Tiao." },
  { zh: "上使告條侯救梁，亞夫不奉詔，堅壁不出；", literal: "The emperor sent word telling Marquis of Tiao to rescue Liang; Yafu did not obey the edict and held his walls firm without coming out;", idiomatic: "The emperor sent word telling Marquis of Tiao to rescue Liang; Yafu did not obey the edict and held his walls firm without coming out;" },
  { zh: "而使弓高侯等將輕騎兵出淮泗口，絕吳、楚兵後，塞其饟道。", literal: "instead he had Marquis of Gonggao and others lead light cavalry out from the Huai-Si mouth, cut off Wu and Chu forces in the rear, and block their supply routes.", idiomatic: "instead he had Marquis of Gonggao and others lead light cavalry out from the Huai-Si mouth, cut off Wu and Chu in the rear, and block their supply routes." },
  { zh: "梁使中大夫韓安國及楚相尚弟羽為將軍；", literal: "Liang appointed Palace Grandee Han Anguo and Chu's chancellor Shang, younger brother Yu, as generals;", idiomatic: "Liang appointed Palace Grandee Han Anguo and Chu's chancellor Shang, younger brother Yu, as generals;" },
  { zh: "羽力戰，安國持重，乃得頗敗吳兵。", literal: "Yu fought with force, Anguo held steady, and only then were they able to defeat Wu troops considerably.", idiomatic: "Yu fought fiercely, Anguo held steady, and only then were they able to defeat Wu troops considerably." },
  { zh: "吳兵欲西，梁城守，不敢西；", literal: "The Wu army wished to go west; Liang held cities in defense and did not dare go west;", idiomatic: "The Wu army wished to advance west; Liang defended its cities and they did not dare advance west;" },
  { zh: "即走條侯軍，會下邑，欲戰。", literal: "they thereupon ran to Marquis of Tiao's army, joined at Xiayi, and wished to fight.", idiomatic: "they thereupon fled to Marquis of Tiao's army, joined him at Xiayi, and wished to give battle." },
  { zh: "條侯堅壁不肯戰；", literal: "Marquis of Tiao held his walls firm and would not fight;", idiomatic: "Marquis of Tiao held his walls firm and would not fight;" },
  { zh: "吳糧絕卒饑，數挑戰，終不出，條侯軍中夜驚，內相攻擊，擾亂至帳下，亞夫堅臥不起，頃之，復定。", literal: "Wu's provisions were cut off and soldiers starved; they repeatedly provoked battle, yet he never came out; at night Marquis of Tiao's army was alarmed, men attacking one another within, disturbance reaching the commander's tent; Yafu lay firm and would not rise; in a moment all was settled again.", idiomatic: "Wu's supplies were cut off and the troops starved; they repeatedly challenged him to battle, yet he never came out; at night Marquis of Tiao's army was thrown into alarm, with men attacking one another within, and the disturbance reached the commander's tent; Yafu lay firm and would not rise; in a moment all was settled again." },
  { zh: "吳奔壁東南陬，亞夫使備西北；", literal: "Wu fled to the southeast corner of the fortification; Yafu sent troops to guard the northwest;", idiomatic: "Wu fled to the southeast corner of the fortification; Yafu sent troops to guard the northwest;" },
  { zh: "已而其精兵果奔西北，不得入。", literal: "Before long their crack troops indeed rushed northwest and could not enter.", idiomatic: "Before long their crack troops indeed rushed northwest and could not break in." },
  { zh: "吳、楚士卒多饑死叛散，乃引而去。", literal: "Wu and Chu soldiers mostly starved, died, rebelled, and scattered; they then withdrew.", idiomatic: "Wu and Chu soldiers mostly starved, died, deserted, and scattered; they then withdrew." },
  { zh: "二月，亞夫出精兵追擊，大破之。", literal: "In the second month Yafu sent out crack troops in pursuit and thoroughly defeated them.", idiomatic: "In the second month Yafu sent crack troops in pursuit and routed them." },
  { zh: "吳王濞棄其軍，與壯士數千人夜亡走；", literal: "King of Wu Liu Pi abandoned his army and with several thousand stalwart men fled by night;", idiomatic: "King of Wu Liu Pi abandoned his army and fled by night with several thousand stalwart men;" },
  { zh: "楚王戊自殺。", literal: "King of Chu Liu Wu killed himself.", idiomatic: "King of Chu Liu Wu killed himself." },
  { zh: "吳王之初發也，吳臣田祿伯為大將軍。", literal: "When the King of Wu first set out, Wu minister Tian Lubo was Grand General.", idiomatic: "When the King of Wu first set out, the Wu minister Tian Lubo served as Grand General." },
  { zh: "田祿伯曰：「兵屯聚而西，無它奇道，難以立功。", literal: "Tian Lubo said: \"If troops mass and go west, with no other surprising route, it is hard to establish merit.", idiomatic: "Tian Lubo said, \"If troops mass and march west, with no other surprising route, it is hard to win merit." },
  { zh: "臣願得五萬人，別循江、淮而上，收淮南、長沙，入武關，與大王會，此亦一奇也。", literal: "Your servant wishes to obtain fifty thousand men, separately follow the Yangzi and Huai upstream, gather Huainan and Changsha, enter Wuguan, and meet with the great king—this is also one stratagem.", idiomatic: "Your servant asks for fifty thousand men to march separately up the Yangzi and Huai, take Huainan and Changsha, enter Wuguan, and join Your Majesty—this too would be a bold stroke." },
  { zh: "」吳王太子諫曰：「王以反為名，此兵難以借人，人亦且反王，奈何？", literal: "\" The crown prince of Wu remonstrated: \"The king takes rebellion as his name; these troops are hard to lend to others, and others would also turn against the king—what then?", idiomatic: "\" The crown prince of Wu remonstrated, \"You take rebellion as your cause; these troops cannot be lent to others, and others would turn against you as well—what then?" },
  { zh: "且擅兵而別，多它利害，徒自損耳！", literal: "Moreover to take troops on one's own authority and separate brings many other harms and benefits—merely self-damage!", idiomatic: "Moreover, to take troops on your own authority and march separately invites all manner of trouble—nothing but harm to yourself!" },
  { zh: "」吳王即不許田祿伯。", literal: "\" The King of Wu then did not permit Tian Lubo.", idiomatic: "\" The King of Wu then refused Tian Lubo." },
  { zh: "吳少將桓將軍說王曰：「吳多步兵，步兵利險；", literal: "Wu young general Huan the General urged the king: \"Wu has many infantry; infantry profit from rugged terrain;", idiomatic: "Wu young general Huan the General urged the king, \"Wu has many foot soldiers; infantry do well in rugged terrain;" },
  { zh: "漢多車騎，車騎利平地，願大王所過城不下，直去，疾西據洛陽武庫，食敖倉粟，阻山河之險以令諸侯，雖無入關，天下固已定矣。", literal: "Han has many chariots and cavalry; chariots and cavalry profit from level ground. I wish that wherever the great king passes, if cities are not taken, pass straight through, hurry west to hold Luoyang's armory, eat Aocang's grain, block the peril of mountains and rivers to command the feudal lords—even without entering the passes, all under Heaven would already be settled.", idiomatic: "Han has many chariots and cavalry; chariots and cavalry do well on level ground. I urge that wherever Your Majesty passes, if a city is not taken, pass it by and press on—hurry west to seize Luoyang's armory, eat the grain of Aocang, and hold the mountain-and-river barriers to command the feudal lords; even without entering the passes, the realm would already be settled." },
  { zh: "大王徐行留下城邑，漢軍車騎至，馳入梁、楚之郊，事敗矣。", literal: "If the great king moves slowly and leaves cities behind, when Han chariots and cavalry arrive and gallop into Liang and Chu's outskirts, the affair is lost.", idiomatic: "If Your Majesty moves slowly and leaves cities behind, when Han chariots and cavalry arrive and gallop into Liang and Chu's outskirts, all is lost." },
  { zh: "」吳王問諸老將，老將曰：「此年少，椎鋒可耳，安知大慮！", literal: "\" The King of Wu asked the various old generals; the old generals said: \"This young fellow—good for smashing at the point, that's all; how would he know great deliberation!", idiomatic: "\" The King of Wu asked the veteran generals; they said, \"This young man is fit to smash the vanguard, nothing more—how would he know grand strategy!" },
  { zh: "」於是王不用桓將軍計。", literal: "\" Thereupon the king did not use General Huan's plan.", idiomatic: "\" Thereupon the king did not adopt General Huan's plan." },
  { zh: "王專並將兵。", literal: "The king personally combined command of the army.", idiomatic: "The king personally took sole command of the army." },
  { zh: "兵未度淮，諸賓客皆得為將、校尉、候、司馬，獨周丘不用。", literal: "Before the army had crossed the Huai, all the guests could become generals, commandants, scouts, and marshals—only Zhou Qiu was not used.", idiomatic: "Before the army had crossed the Huai, every guest was made a general, commandant, scout, or marshal—only Zhou Qiu was passed over." },
  { zh: "周丘者，下邳人，亡命吳，酤酒無行；", literal: "Zhou Qiu was a man of Xiapi; a fugitive in Wu, he sold wine and had no conduct;", idiomatic: "Zhou Qiu was a man of Xiapi, a fugitive in Wu who sold wine and lived without propriety;" },
  { zh: "王薄之，不任。", literal: "the king slighted him and did not employ him.", idiomatic: "the king looked down on him and gave him no post." },
  { zh: "周丘乃上謁，說王曰：「臣以無能，不得待罪行間。", literal: "Zhou Qiu thereupon went up to an audience and urged the king: \"Your servant, lacking ability, could not wait on you among those guilty of crimes.", idiomatic: "Zhou Qiu thereupon had an audience and urged the king, \"Your servant, being without ability, could not serve you among those bearing criminal guilt." },
  { zh: "臣非敢求有所將也，願請王一漢節，必有以報。", literal: "Your servant does not dare to ask to command troops; I wish to request one Han staff from the king—there will surely be repayment.", idiomatic: "I do not dare ask to command troops; I ask only for one Han staff from Your Majesty—I shall surely repay you." },
  { zh: "」王乃予之。", literal: "\" The king then gave it to him.", idiomatic: "\" The king then gave it to him." },
  { zh: "周丘得節，夜馳入下邳；", literal: "Zhou Qiu obtained the staff; by night he galloped into Xiapi;", idiomatic: "Zhou Qiu obtained the staff and by night galloped into Xiapi;" },
  { zh: "下邳時聞吳反，皆城守。", literal: "Xiapi at the time had heard Wu rebelled and all fortified and defended.", idiomatic: "Xiapi had already heard that Wu had rebelled, and all were fortifying and defending." },
  { zh: "至傳舍，召令入戶，使從者以罪斬令，遂召昆弟所善豪吏告曰：「吳反，兵且至，屠下邳不過食頃；", literal: "Reaching the relay station, he summoned the magistrate to enter; he had his followers execute the magistrate on a charge, then summoned his brothers and favored bold officers and told them: \"Wu has rebelled, troops are about to arrive, slaughter of Xiapi would not exceed the time of a meal;", idiomatic: "Reaching the relay station, he summoned the magistrate inside and had his followers execute him on a charge; he then summoned his brothers and favored bold officers and said, \"Wu has rebelled, troops are about to arrive, and Xiapi will be slaughtered within the time of a meal;" },
  { zh: "今先下，家室必完，能者封侯矣。", literal: "if you submit first, households will surely be preserved; the capable will be enfeoffed as marquises.", idiomatic: "submit first and your households will be spared; the capable will be enfeoffed as marquises." },
  { zh: "」出，乃相告，下邳皆下。", literal: "\" Going out, they told one another, and all Xiapi submitted.", idiomatic: "\" Going out, they spread the word, and all Xiapi submitted." },
  { zh: "周丘一夜得三萬人，使人報吳王，遂將其兵北略城邑；", literal: "Zhou Qiu in one night obtained thirty thousand men, sent men to report to the King of Wu, and thereupon led his army north raiding cities;", idiomatic: "Zhou Qiu in one night raised thirty thousand men, sent word to the King of Wu, and thereupon led his troops north raiding cities;" },
  { zh: "比至陽城，兵十餘萬，破陽城中尉軍；", literal: "by the time he reached Yangcheng, troops exceeded one hundred thousand; he broke the Central Commandant's army at Yangcheng;", idiomatic: "by the time he reached Yangcheng his force exceeded one hundred thousand; he defeated the Central Commandant's army at Yangcheng;" },
  { zh: "聞吳王敗走，自度無與共成功，即引兵歸下邳，未至，疽發背死。", literal: "hearing the King of Wu was defeated and fleeing, he reckoned he had no one with whom to succeed together, thereupon led troops back to Xiapi; before arriving, an ulcer broke out on his back and he died.", idiomatic: "hearing the King of Wu was defeated and fleeing, he judged that he had no partner with whom to succeed, and led his troops back toward Xiapi; before he arrived, a carbuncle broke out on his back and he died." },
  { zh: "----6壬午晦，日有食之。", literal: "----6 On renwu, the last day of the month, there was a solar eclipse.", idiomatic: "----6 On renwu, the last day of the month, there was a solar eclipse." },
  { zh: "----7吳王之棄軍亡也，軍遂潰，往往稍降太尉條侯及梁軍。", literal: "----7 When the King of Wu abandoned his army and fled, the army thereupon collapsed; here and there they gradually submitted to Grand Commandant Marquis of Tiao and the army of Liang.", idiomatic: "----7 When the King of Wu abandoned his army and fled, the army collapsed; here and there men gradually surrendered to Grand Commandant Marquis of Tiao and the army of Liang." },
  { zh: "吳王渡淮，走丹徒，保東越，兵可萬餘人，收聚亡卒。", literal: "The King of Wu crossed the Huai, fled to Dantu, sheltered with Dongyue, troops about ten thousand and more, gathering scattered fugitive soldiers.", idiomatic: "The King of Wu crossed the Huai, fled to Dantu, and took refuge with Dongyue with a force of more than ten thousand, gathering scattered fugitives." },
  { zh: "漢使人以利啖東越，東越即紿吳王出勞軍，使人鏦殺吳王，盛其頭，馳傳以聞。", literal: "Han sent men to bait Dongyue with profit; Dongyue then deceived the King of Wu to come out and comfort the army, sent men to spear-kill the King of Wu, packed his head, and galloped by relay to report.", idiomatic: "Han sent men to entice Dongyue with profit; Dongyue then tricked the King of Wu into coming out to review the troops, had him speared to death, packed his head, and galloped by relay to report." },
  { zh: "吳太子駒亡走閩越。", literal: "The crown prince of Wu Ju fled to Minyue.", idiomatic: "The crown prince of Wu, Ju, fled to Minyue." },
  { zh: "吳、楚反，凡三月，皆破滅，於是諸將乃以太尉謀為是；", literal: "The Wu-Chu rebellion, altogether three months, all were broken and extinguished; thereupon the various generals then considered the Grand Commandant's plan correct;", idiomatic: "The Wu-Chu rebellion lasted three months in all before all were destroyed; thereupon the generals judged the Grand Commandant's plan correct;" },
  { zh: "然梁王由此與太尉有隙。", literal: "yet the King of Liang from this had a rift with the Grand Commandant.", idiomatic: "yet from this the King of Liang bore a grudge against the Grand Commandant." },
  { zh: "三王之圍臨菑也，齊王使路中大夫告於天子。", literal: "When the three kings besieged Linzi, the King of Qi sent an Imperial Messenger on the Road to report to the Son of Heaven.", idiomatic: "When the three kings besieged Linzi, the King of Qi sent an Imperial Messenger on the Road to report to the Son of Heaven." },
  { zh: "天子復令路中大夫還報，告齊王堅守，「漢兵今破吳楚矣。", literal: "The Son of Heaven again ordered the Imperial Messenger on the Road to return and report, telling the King of Qi to hold firm: \"Han troops have now broken Wu and Chu.", idiomatic: "The Son of Heaven again ordered the Imperial Messenger on the Road to return with word telling the King of Qi to hold firm: \"Han troops have now defeated Wu and Chu." },
  { zh: "」路中大夫至，三國兵圍臨菑數重，無從入。", literal: "\" When the Imperial Messenger on the Road arrived, the armies of the three states besieged Linzi in many rings; he could not enter.", idiomatic: "\" When the Imperial Messenger on the Road arrived, the armies of the three states had Linzi encircled in many rings and he could not get in." },
  { zh: "三國將與路中大夫盟曰：「若反言：『漢已破矣，齊趣下三國，不，且見屠。", literal: "The generals of the three states would ally with the Imperial Messenger on the Road, saying: \"If you speak contrary: 'Han is already broken; Qi hurry and submit to the three states—if not, you will soon be slaughtered.", idiomatic: "The generals of the three states made a pact with the Imperial Messenger on the Road, saying, \"If you speak falsely: 'Han is already defeated; Qi must hurry and submit to the three states—if not, you will soon be slaughtered." },
  { zh: "』」路中大夫既許，至城下，望見齊王曰：「漢已發兵百萬，使太尉亞夫擊破吳、楚，方引兵救齊，齊必堅守無下！", literal: "'\" The Imperial Messenger on the Road having agreed, when he reached below the wall and saw the King of Qi, he said: \"Han has already sent a million troops; the Grand Commandant Yafu has broken Wu and Chu and is just leading troops to rescue Qi—Qi must hold firm and not submit!", idiomatic: "'\" The Imperial Messenger on the Road having agreed, when he reached the foot of the wall and saw the King of Qi, he said, \"Han has already sent a million troops; Grand Commandant Yafu has defeated Wu and Chu and is leading troops to rescue Qi—Qi must hold firm and not submit!" },
  { zh: "」三國將誅路中大夫。", literal: "\" The generals of the three states would execute the Imperial Messenger on the Road.", idiomatic: "\" The generals of the three states would have executed the Imperial Messenger on the Road." },
  { zh: "齊初圍急，陰與三國通謀，約未定；", literal: "At first when the siege was pressing, Qi secretly communicated conspiracy with the three states; the covenant was not settled;", idiomatic: "When the siege was first pressing, Qi secretly communicated with the three states; the agreement was not yet settled;" },
  { zh: "會路中大夫從漢來，其大臣乃復勸王無下三國。", literal: "when the Imperial Messenger on the Road came from Han, his great ministers thereupon again urged the king not to submit to the three states.", idiomatic: "when the Imperial Messenger on the Road came from Han, the great ministers again urged the king not to submit to the three states." },
  { zh: "會漢將欒布、平陽侯等兵至齊，擊破三國兵。", literal: "When Han generals Luan Bu, Marquis of Pingyang, and others' troops reached Qi, they struck and broke the armies of the three states.", idiomatic: "When Han generals Luan Bu, Marquis of Pingyang, and others reached Qi with their troops, they defeated the armies of the three states." },
  { zh: "解圍已，後聞齊初與三國有謀，將欲移兵伐齊。", literal: "After the siege was lifted, afterward they heard Qi at first had conspiracy with the three states; they were about to move troops to attack Qi.", idiomatic: "After the siege was lifted, they later heard that Qi had at first conspired with the three states and were about to move troops to attack Qi." },
  { zh: "齊孝王懼，飲藥自殺。", literal: "King Xiao of Qi was afraid and drank poison and killed himself.", idiomatic: "King Xiao of Qi, in fear, drank poison and killed himself." },
  { zh: "膠西、膠東、菑川王各引兵歸國。", literal: "The kings of Jiaoxi, Jiaodong, and Zichuan each led troops back to their states.", idiomatic: "The kings of Jiaoxi, Jiaodong, and Zichuan each led their troops back to their states." },
  { zh: "膠西王徒跣、席蒿、飲水謝太后。", literal: "The King of Jiaoxi went barefoot, spread artemisia as a mat, drank water, and apologized to the Empress Dowager.", idiomatic: "The King of Jiaoxi went barefoot, spread artemisia for a mat, drank water, and apologized to the Empress Dowager." },
  { zh: "王太子德曰：「漢兵還，臣觀之，已罷，可襲，願收王餘兵擊之！", literal: "The king's crown prince De said: \"Han troops have returned; your servant observed them—they are already weary; they can be raided; I wish to gather the king's remaining troops and strike them!", idiomatic: "The king's crown prince De said, \"Han troops have returned; I observed them—they are already exhausted and can be attacked; I ask to gather Your Majesty's remaining troops and strike them!" },
  { zh: "不勝而逃入海，未晚也。", literal: "If we do not win, fleeing into the sea is not yet late.", idiomatic: "If we do not win, fleeing to sea is not yet too late." },
  { zh: "」王曰：「吾士卒皆已壞，不可用。", literal: "\" The king said: \"My soldiers are all already ruined; they cannot be used.", idiomatic: "\" The king said, \"My troops are all already ruined and cannot be used." },
  { zh: "」弓高侯韓頹當遺膠西王書曰：「奉詔誅不義，降者赦除其罪，復故；", literal: "\" Marquis of Gonggao Han Tuidang sent a letter to the King of Jiaoxi: \"By edict we execute the unrighteous; those who submit are pardoned, their crimes removed, and restored to former status;", idiomatic: "\" Marquis of Gonggao Han Tuidang sent a letter to the King of Jiaoxi: \"By edict we punish the unrighteous; those who submit are pardoned, their crimes removed, and restored to former standing;" },
  { zh: "不降者滅之。", literal: "those who do not submit are extinguished.", idiomatic: "those who do not submit are destroyed." },
  { zh: "王何處？", literal: "Where is the king?", idiomatic: "Where is the king?" },
  { zh: "須以從事。", literal: "We must deal with you accordingly.", idiomatic: "We must deal with you accordingly." },
  { zh: "」王肉袒叩頭，詣漢軍壁謁曰：「臣卬奉法不謹，驚駭百姓，乃苦將軍遠道至於窮國，敢請菹醢之罪！", literal: "\" The king went bare-chested and knocked his head, went to the Han army's rampart and called: \"Your servant Ang failed to observe the law carefully, startled and terrified the hundred surnames, and thus troubled the general to come far on the road to this impoverished state—I dare request the crime of being minced into paste!", idiomatic: "\" The king went bare-chested and knocked his head, went to the Han army's rampart and said, \"Your servant Ang failed to observe the law carefully, startled and terrified the people, and thus troubled the general to come far to this impoverished state—I dare request the punishment of being minced into paste!" },
  { zh: "」弓高侯執金鼓見之曰：「王苦軍事，願聞王發兵狀。", literal: "\" The Marquis of Gonggao held golden drums and received him, saying: \"The king has suffered military matters; I wish to hear the state of the king's dispatching troops.", idiomatic: "\" The Marquis of Gonggao, holding golden drums, received him and said, \"Your Majesty has suffered in war; I wish to hear how you raised your troops." },
  { zh: "」王頓首膝行，對曰：「今者晁錯天子用事臣，變更高皇帝法令，侵奪諸侯地。", literal: "\" The king knocked his head and crawled on his knees, replying: \"Now Chao Cuo, the Son of Heaven's minister in power, changed and raised the August Emperor's laws and statutes, encroaching on and seizing feudal lords' lands.", idiomatic: "\" The king knocked his head and crawled on his knees, replying, \"Chao Cuo, the Son of Heaven's minister in power, has altered and raised the August Emperor's laws and statutes and encroached on and seized the feudal lords' lands." },
  { zh: "卬等以為不義，恐其敗亂天下，七國發兵且誅錯。", literal: "Ang and others considered this unrighteous, feared he would corrupt and disorder all under Heaven; the seven states dispatched troops intending to execute Chao Cuo.", idiomatic: "Ang and others considered this unrighteous and feared he would throw the realm into disorder; the seven states raised troops to execute Chao Cuo." },
  { zh: "今聞錯已誅，卬等謹已罷兵歸。", literal: "Now hearing Chao Cuo has been executed, Ang and others respectfully have already ceased troops and returned.", idiomatic: "Now that we hear Chao Cuo has been executed, Ang and others have respectfully already ceased our troops and returned." },
  { zh: "」將軍曰：「王苟以錯為不善，何不以聞？", literal: "\" The general said: \"If the king truly considered Cuo not good, why not report it?", idiomatic: "\" The general said, \"If Your Majesty truly considered Cuo wrong, why did you not report it?" },
  { zh: "及未有詔、虎符，擅發兵擊義國？", literal: "And before there was an edict and tiger tally, presumptuously dispatch troops to strike righteous states?", idiomatic: "And before there was an edict and tiger tally, why did you presumptuously raise troops to attack loyal states?" },
  { zh: "以此觀之，意非徒欲誅錯也。", literal: "From this observing, the intent was not merely to execute Chao Cuo.", idiomatic: "Judging from this, your intent was not merely to execute Chao Cuo." },
  { zh: "」乃出詔書，為王讀之，曰：「王其自圖！", literal: "\" He thereupon produced the edict and read it for the king: \"The king must consider for himself!", idiomatic: "\" He thereupon produced the edict and read it to the king: \"Your Majesty must consider for yourself!" },
  { zh: "」王曰：「如卬等死有餘罪！", literal: "\" The king said: \"For Ang and others death leaves surplus guilt!", idiomatic: "\" The king said, \"For Ang and others death would still leave guilt to spare!" },
  { zh: "」遂自殺，太后、太子皆死。", literal: "\" Thereupon he killed himself; the empress dowager and crown prince both died.", idiomatic: "\" Thereupon he killed himself; the empress dowager and crown prince both died." },
  { zh: "膠東王、菑川王、濟南王皆伏誅。", literal: "The kings of Jiaodong, Zichuan, and Jinan all were executed before the law.", idiomatic: "The kings of Jiaodong, Zichuan, and Jinan were all executed." },
  { zh: "酈將軍兵至趙，趙王引兵還邯鄲城守。", literal: "General Li's troops reached Zhao; the King of Zhao led troops back to Handan and fortified the city to defend.", idiomatic: "General Li's troops reached Zhao; the King of Zhao led his troops back to Handan and held the city." },
  { zh: "酈寄攻之，七月不能下。", literal: "Li Ji attacked it; seven months and he could not take it.", idiomatic: "Li Ji besieged it for seven months without taking it." },
  { zh: "匈奴聞吳、楚敗，亦不肯入邊。", literal: "The Xiongnu heard Wu and Chu were defeated and also would not enter the border.", idiomatic: "The Xiongnu heard that Wu and Chu were defeated and also refused to cross the border." },
  { zh: "欒布破齊還，並兵引水灌趙城。", literal: "Luan Bu, having broken Qi, returned, combined troops, and led water to flood the Zhao city.", idiomatic: "Luan Bu, having defeated Qi, returned, combined forces, and led water to flood the Zhao capital." },
  { zh: "城壞，王遂自殺。", literal: "The city wall broke; the king thereupon killed himself.", idiomatic: "The walls collapsed; the king thereupon killed himself." },
  { zh: "帝以齊首善，以迫劫有謀，非其罪也，召立齊孝王太子壽，是為懿王。", literal: "The emperor because Qi first did good, and its coercion and conspiracy had a plot not its own crime, summoned and established King Xiao of Qi's crown prince Shou—this was King Yi.", idiomatic: "The emperor, because Qi had been the first to do right and its coercion and conspiracy were not its own doing, summoned and enthroned King Xiao of Qi's crown prince Shou as King Yi." },
  { zh: "濟北王亦欲自殺，幸全其妻子。", literal: "The King of Jibei also wished to kill himself but fortunately preserved his wife and children.", idiomatic: "The King of Jibei also wished to kill himself but was fortunate enough to preserve his wife and children." },
  { zh: "齊人公孫玃謂濟北王曰：「臣請試為大王明說梁王，通意天子；", literal: "The Qi man Gongsun Yan said to the King of Jibei: \"Your servant requests to try for the great king to clarify and speak to the King of Liang, conveying intent to the Son of Heaven;", idiomatic: "The Qi man Gongsun Yan said to the King of Jibei, \"Your servant asks to try to speak plainly for Your Majesty to the King of Liang and convey your intent to the Son of Heaven;" },
  { zh: "說而不用，死未晚也。", literal: "if persuasion is not used, death is not yet late.", idiomatic: "if he is not persuaded, death is not yet too late." },
  { zh: "」公孫玃遂見梁王曰：「夫濟北之地，東接強齊，南牽吳、越，北脅燕、趙。", literal: "\" Gongsun Yan thereupon saw the King of Liang: \"The territory of Jibei—east it adjoins strong Qi, south it is dragged by Wu and Yue, north it is coerced by Yan and Zhao.", idiomatic: "\" Gongsun Yan thereupon saw the King of Liang and said, \"The territory of Jibei adjoins powerful Qi on the east, is pulled by Wu and Yue on the south, and is menaced by Yan and Zhao on the north." },
  { zh: "此四分五裂之國。", literal: "This is a state split into four and five pieces.", idiomatic: "It is a land split four and five ways." },
  { zh: "權不足以自守，勁不足以捍寇，又非有奇怪雲以待難也；", literal: "Its power is insufficient to defend itself, its strength insufficient to repel invaders, and moreover it lacks strange clouds to await calamity;", idiomatic: "Its authority is insufficient to defend itself, its strength insufficient to repel invaders, and it has no miraculous portents to await disaster;" },
  { zh: "雖墜言於吳，非其正計也。", literal: "though it fell in speech with Wu, that was not its proper plan.", idiomatic: "though it fell in with Wu in word, that was not its proper course." },
  { zh: "鄉使濟北見情實，示不從之端，則吳必先歷齊，畢濟北，招燕、趙而總之，如此，則山東之從結而無隙矣。", literal: "Had Jibei shown true circumstances and displayed the start of not following, then Wu would first have passed through Qi, finished Jibei, summoned Yan and Zhao and gathered them—in such case the Shandong alliance would have been tied with no gap.", idiomatic: "Had Jibei shown its true circumstances and made clear that it would not follow, Wu would first have passed through Qi, finished Jibei, and summoned Yan and Zhao to gather them—then the Shandong alliance would have been knit without a gap." },
  { zh: "今吳王連諸侯之兵，驅白徒之眾，西與天子急衡，濟北獨底節不下；", literal: "Now the King of Wu joined the feudal lords' troops, drove the masses of common levies, west urgently contended with the Son of Heaven, while Jibei alone held its integrity and would not submit;", idiomatic: "Now the King of Wu joined the feudal lords' armies, drove the masses of common levies, and pressed west to contend with the Son of Heaven, while Jibei alone held firm and would not submit;" },
  { zh: "使吳失與而無助，跬步獨進，瓦解土崩，破敗而不救者，未必非濟北之力也。", literal: "causing Wu to lose allies and have no aid, inch by inch advancing alone, collapsing like earth and disintegrating like a dam, broken and defeated with none to save—this was perhaps not without Jibei's force.", idiomatic: "causing Wu to lose allies and have no help, to advance alone step by step, and to collapse and break without rescue—this was perhaps not without Jibei's doing." },
  { zh: "夫以區區之濟北而與諸侯爭強，是以羔犢之弱而扞虎狼之敵也。", literal: "For petty Jibei to contend for supremacy with the feudal lords is to use the weakness of lamb and calf to repel tiger and wolf enemies.", idiomatic: "For petty Jibei to contend for supremacy with the feudal lords is to pit the weakness of a lamb or calf against tiger-and-wolf foes." },
  { zh: "守職不橈，可謂誠一矣。", literal: "Holding office without bending—this may be called sincere unity.", idiomatic: "Holding office without bending—this may be called single-minded loyalty." },
  { zh: "功義如此，尚見疑於上，脅肩低首，累足撫衿，使有自悔不前之心，非社稷之利也。", literal: "Merit and righteousness such as this, yet still suspected above, shrugging shoulders and bowing head, piling feet and stroking the lapel, causing a mind of self-reproach and not advancing—this is not profit to the altars of soil and grain.", idiomatic: "With merit and righteousness such as this, yet still suspected above, shrinking the shoulders and bowing the head, standing on tiptoe and clutching the lapel, until one has a mind to repent and not advance—this is not to the altars' benefit." },
  { zh: "臣恐籓臣守職者疑之。", literal: "Your servant fears that feudatory officials holding office will doubt.", idiomatic: "Your servant fears that feudatory lords who hold their posts faithfully will be put in doubt." },
  { zh: "臣竊料之，能歷西山，徑長樂，抵未央，攘袂而正議者，獨大王耳。", literal: "Your servant privately reckons: able to pass Western Hills, go straight through Changle, reach Weiyang, roll up sleeves and speak uprightly—only the great king.", idiomatic: "Your servant privately judges that only Your Majesty can pass Western Hills, go straight through Changle, reach Weiyang Palace, roll up your sleeves, and speak forthrightly." },
  { zh: "上有全亡之功，下有安百姓之名，德淪於骨髓，恩加於無窮，願大王留意詳惟之。", literal: "Above there is merit in wholly saving from death; below there is a name for settling the hundred surnames; virtue soaking into marrow and bones, grace extending without end—I wish the great king to pay attention and carefully consider.", idiomatic: "Above you would have the merit of wholly saving a man from death; below you would have the name of settling the people; virtue would soak to the marrow and grace extend without end—I urge Your Majesty to consider this carefully." },
  { zh: "」孝王大悅，使人馳以聞；", literal: "\" King Xiao was greatly pleased and sent men galloping to report;", idiomatic: "\" King Xiao was greatly pleased and sent men galloping to report;" },
  { zh: "濟北王得不坐，徙封於菑川。", literal: "the King of Jibei was not punished by execution, and was moved and enfeoffed at Zichuan.", idiomatic: "the King of Jibei was not executed but was transferred and enfeoffed at Zichuan." },
  { zh: "----8河間王太傅衛綰擊吳、楚有功，拜為中尉。", literal: "----8 The Grand Tutor of the King of Hejian Wei Wan struck Wu and Chu with merit and was appointed Commandant of the Guards.", idiomatic: "----8 The Grand Tutor of the King of Hejian, Wei Wan, who had struck Wu and Chu with merit, was appointed Commandant of the Guards." },
  { zh: "綰以中郎將事文帝，醇謹無它。", literal: "Wan as Central Palace General served Emperor Wen—pure, careful, and without other [faults].", idiomatic: "Wan served Emperor Wen as Central Palace General, pure and careful, with no other faults." },
  { zh: "上為太子時，召文帝左右飲，而綰稱病不行。", literal: "When the Emperor was Crown Prince, he summoned Wen's close attendants to drink, but Wan claimed illness and did not go.", idiomatic: "When the Emperor was crown prince he summoned Wen's close attendants to drink, but Wan pleaded illness and stayed away." },
  { zh: "文帝且崩，屬上曰：「綰長者，善遇之。", literal: "When Wen was about to die, he entrusted the Emperor, saying: \"Wan is an elder—treat him well.", idiomatic: "As Wen lay dying he entrusted the Emperor, saying, \"Wan is an elder—treat him well." },
  { zh: "」故上亦寵任焉。", literal: "\" Therefore the Emperor also favored and employed him.", idiomatic: "\" Therefore the Emperor also favored and employed him." },
  { zh: "----9夏，六月，乙亥，詔：「吏民為吳王濞等所詿誤當坐及逋逃亡軍者，皆赦之。", literal: "----9 In summer, the sixth month, on yihai, an edict: \"Officials and commoners misled by King of Wu Liu Pi and the rest who ought to be punished, and deserters who fled the army—all are pardoned.", idiomatic: "----9 In summer, the sixth month, on the day yihai, an edict ran: \"Officials and commoners misled by King of Wu Liu Pi and the rest who ought to be punished, and deserters who fled the army—all are pardoned." },
  { zh: "」帝欲以吳王弟德哀侯廣之子續吳，以楚元王子禮續楚。", literal: "\" The Emperor wished to continue Wu through the son of De'ai Marquis Guang, younger brother of the King of Wu, and to continue Chu through Prince Li of Chu Yuan.", idiomatic: "\" The Emperor wished to continue the Wu line through the son of De'ai Marquis Guang, the King of Wu's younger brother, and to continue Chu through Prince Li, son of King Yuan of Chu." },
  { zh: "竇太后曰：「吳王，老人也，宜為宗室順善；", literal: "Empress Dowager Dou said: \"The King of Wu is an old man who ought to have been compliant and good as a member of the imperial clan;", idiomatic: "Empress Dowager Dou said, \"The King of Wu is an old man who ought to have been a compliant, dutiful kinsman of the house;" },
  { zh: "今乃首率七國紛亂天下，奈何續其後！", literal: "yet now he was first to lead the seven kingdoms in disordering all under Heaven—how can we continue his line!", idiomatic: "yet he was first to lead the seven kingdoms in throwing the realm into chaos—how can we continue his line!" },
  { zh: "」不許吳，許立楚後。", literal: "\" She did not permit Wu; she permitted establishing a successor for Chu.", idiomatic: "\" She refused Wu; she allowed a successor for Chu." },
  { zh: "乙亥，徙淮陽王餘為魯王；", literal: "On yihai, Prince of Huaiyang Yu was moved to be King of Lu;", idiomatic: "On yihai Prince Yu of Huaiyang was moved to be King of Lu;" },
  { zh: "南王非為江都王，王故吳地；", literal: "the King of the South Fei was made King of Jiangdu, ruling the former Wu territory;", idiomatic: "King Fei of the South was made King of Jiangdu, ruling the former Wu lands;" },
  { zh: "立宗正禮為楚王；", literal: "Director of the Imperial Clan Li was installed as King of Chu;", idiomatic: "Director of the Imperial Clan Li was installed as King of Chu;" },
  { zh: "立皇子端為膠西王，勝為中山王。", literal: "the Emperor's son Duan was installed as King of Jiaoxi and Sheng as King of Zhongshan.", idiomatic: "the Emperor's sons Duan and Sheng were installed as kings of Jiaoxi and Zhongshan." },
  { zh: "----1春，復置關，用傳出入。", literal: "----1 In spring, the passes were restored; travel permits were required for entry and exit.", idiomatic: "----1 In spring the passes were restored and travel permits were required for entry and exit." },
  { zh: "----2夏，四月，己巳，立子榮為皇太子，徹為膠東王。", literal: "----2 In summer, the fourth month, on jisi, the son Rong was installed as Crown Prince and Che as King of Jiaodong.", idiomatic: "----2 In summer, the fourth month, on the day jisi, the son Rong was installed as crown prince and Che as King of Jiaodong." },
  { zh: "----3六月，赦天下。", literal: "----3 In the sixth month, he pardoned all under Heaven.", idiomatic: "----3 In the sixth month he proclaimed a general amnesty." },
  { zh: "----4秋，七月，臨江王閼薨。", literal: "----4 In autumn, the seventh month, Prince of Linjiang Min died.", idiomatic: "----4 In autumn, the seventh month, Prince Min of Linjiang died." },
  { zh: "----5冬，十月，戊戌晦，日有食之。", literal: "----5 In winter, the tenth month, on the last day wuxu, there was an eclipse of the sun.", idiomatic: "----5 In winter, the tenth month, on the last day wuxu, the sun was eclipsed." },
  { zh: "----6初，吳、楚七國反，吳使者至淮南，淮南王欲發兵應之。", literal: "----6 At the beginning, when Wu and Chu and the seven kingdoms rebelled, Wu's envoy reached Huainan; the King of Huainan wished to mobilize troops to respond.", idiomatic: "----6 At first, when Wu, Chu, and the seven kingdoms rebelled, Wu's envoy reached Huainan and the King of Huainan wished to raise troops in support." },
  { zh: "其相曰：「王必欲應吳，臣願為將。", literal: "His chancellor said: \"If Your Majesty must respond to Wu, your servant wishes to be general.", idiomatic: "His chancellor said, \"If Your Majesty must answer Wu, your servant will serve as general." },
  { zh: "」王乃屬之。", literal: "\" The king thereupon entrusted him.", idiomatic: "\" The king thereupon entrusted him." },
  { zh: "相已將兵，因城守，不聽王而為漢，漢亦使曲城侯將兵救淮南，以故得完。", literal: "Once the chancellor had taken command of the troops, he fortified and held the city, did not heed the king, and sided with Han; Han also sent Marquis of Qucheng with troops to rescue Huainan—therefore it was preserved intact.", idiomatic: "Once the chancellor had the troops he walled the city and held it, ignored the king, and sided with Han; Han also sent Marquis of Qucheng with troops to relieve Huainan, and so it remained intact." },
  { zh: "吳使者至廬江，廬江王不應，而往來使越。", literal: "When Wu's envoy reached Lujiang, the King of Lujiang did not respond but instead sent envoys back and forth to Yue.", idiomatic: "When Wu's envoy reached Lujiang the King of Lujiang did not respond but kept sending envoys to Yue." },
  { zh: "至衡山，衡山王堅守無二心。", literal: "At Hengshan, the King of Hengshan held firm with no second intent.", idiomatic: "At Hengshan the King of Hengshan held firm and showed no divided loyalty." },
  { zh: "及吳、楚已破，衡山王入朝。", literal: "When Wu and Chu had already been defeated, the King of Hengshan entered court.", idiomatic: "After Wu and Chu were defeated the King of Hengshan came to court." },
  { zh: "上以為貞信，勞苦之，曰：「南方卑濕。", literal: "The Emperor took him to be steadfast and faithful, comforted him for his hardships, and said: \"The south is low and damp.", idiomatic: "The Emperor judged him steadfast and faithful, comforted him for his hardships, and said, \"The south is low and damp." },
  { zh: "」徙王王於濟北以褒之。", literal: "\" He moved the king to be king at Jibei as a reward.", idiomatic: "\" He moved him to be king of Jibei as a reward." },
  { zh: "廬江王以邊越，數使使相交，徙為衡山王，王江北。", literal: "The King of Lujiang, because he bordered Yue and repeatedly sent envoys to exchange with them, was moved to be King of Hengshan, ruling north of the river.", idiomatic: "The King of Lujiang, because he bordered Yue and repeatedly exchanged envoys with them, was moved to be King of Hengshan, ruling north of the Yangzi." },
  { zh: "----1春，正月，作陽陵邑。", literal: "----1 In spring, the first month, the Yangling settlement was built.", idiomatic: "----1 In spring, the first month, the Yangling settlement was built." },
  { zh: "夏，募民徙陽陵，賜錢二十萬。", literal: "In summer, the people were recruited to move to Yangling; each was granted two hundred thousand cash.", idiomatic: "In summer commoners were recruited to move to Yangling, each granted two hundred thousand cash." },
  { zh: "----2遣公主嫁匈奴單于。", literal: "----2 A princess was sent to marry the Xiongnu chanyu.", idiomatic: "----2 A princess was sent to marry the Xiongnu chanyu." },
  { zh: "----3徙廣川王彭祖為趙王。", literal: "----3 King Pengzu of Guangchuan was moved to be King of Zhao.", idiomatic: "----3 King Pengzu of Guangchuan was moved to be King of Zhao." },
  { zh: "----4濟北貞王勃薨。", literal: "----4 Steadfast King Bo of Jibei died.", idiomatic: "----4 Steadfast King Bo of Jibei died." },
  { zh: "----1冬，十二月，雷，霖雨。", literal: "----1 In winter, the twelfth month, there was thunder and soaking rain.", idiomatic: "----1 In winter, the twelfth month, there was thunder and soaking rain." },
  { zh: "----2初，上為太子，薄太后以薄氏女為妃；", literal: "----2 At the beginning, when the Emperor was crown prince, Empress Dowager Bo made a woman of the Bo clan his consort;", idiomatic: "----2 At first, when the Emperor was crown prince, Empress Dowager Bo made a woman of the Bo clan his consort;" },
  { zh: "及即位，為皇后，無寵。", literal: "when he took the throne she became empress but had no favor.", idiomatic: "when he took the throne she became empress but won no favor." },
  { zh: "秋，九月，皇后薄氏廢。", literal: "In autumn, the ninth month, Empress Bo was deposed.", idiomatic: "In autumn, the ninth month, Empress Bo was deposed." },
  { zh: "----3楚文王禮薨。", literal: "----3 King Wen Li of Chu died.", idiomatic: "----3 King Wen Li of Chu died." },
  { zh: "----4初，燕王臧荼有孫女曰臧兒，嫁為槐里王仲妻，生男信與兩女而仲死；", literal: "----4 At the beginning, King Zang of Yan had a granddaughter named Zang Er, who married as wife to King Zhong of Huaili, bore a son Xin and two daughters, and then Zhong died;", idiomatic: "----4 At first, King Zang of Yan had a granddaughter named Zang Er who married King Zhong of Huaili, bore a son Xin and two daughters, and then Zhong died;" },
  { zh: "更嫁長陵田氏，生男蚡、勝。", literal: "she remarried into the Tian clan of Changling and bore sons Fen and Sheng.", idiomatic: "she remarried into the Tian clan of Changling and bore sons Fen and Sheng." },
  { zh: "文帝時，臧兒長女為金王孫婦，生女俗。", literal: "In Emperor Wen's time Zang Er's eldest daughter was wife to King Sun of Jin and bore a daughter Su.", idiomatic: "In Emperor Wen's time Zang Er's eldest daughter was wife to King Sun of Jin and bore a daughter Su." },
  { zh: "臧兒卜筮之，曰：「兩女皆當貴。", literal: "Zang Er divined by milfoil and said: \"Both daughters are destined for eminence.", idiomatic: "Zang Er divined by milfoil and was told, \"Both daughters are destined for eminence." },
  { zh: "」臧兒乃奪金氏婦，金氏怒，不肯予決；", literal: "\" Zang Er then seized the wife from the Jin clan; the Jin clan was angry and would not grant a divorce;", idiomatic: "\" Zang Er then seized her from the Jin household; the Jins were angry and would not grant a divorce;" },
  { zh: "內之太子宮，生男徹。", literal: "she brought her into the crown prince's palace, where she bore a son Che.", idiomatic: "she brought her into the crown prince's palace, where she bore a son Che." },
  { zh: "徹方在身時，王夫人夢日入其懷。", literal: "While Che was still in the womb, Lady Wang dreamed the sun entered her bosom.", idiomatic: "While Che was still in the womb, Lady Wang dreamed the sun entered her bosom." },
  { zh: "及帝即位，長男榮為太子。", literal: "When the Emperor took the throne, the eldest son Rong was crown prince.", idiomatic: "When the Emperor took the throne, the eldest son Rong was crown prince." },
  { zh: "其母栗姬，齊人也。", literal: "His mother Lady Li was a woman of Qi.", idiomatic: "His mother Lady Li was from Qi." },
  { zh: "長公主嫖欲以女嫁太子，栗姬以後宮諸美人皆因長公主見帝，故怒而不許；", literal: "The Eldest Princess Piao wished to marry her daughter to the crown prince; Lady Li, because the various beauties of the inner palace all reached the Emperor through the Eldest Princess, was angry and would not agree;", idiomatic: "The Eldest Princess Piao wished to marry her daughter to the crown prince; Lady Li, because the palace beauties all reached the Emperor through the Eldest Princess, was angry and refused;" },
  { zh: "長公主欲與王夫人男徹，王夫人許之。", literal: "the Eldest Princess wished to give her daughter to Lady Wang's son Che, and Lady Wang agreed.", idiomatic: "the Eldest Princess then sought Lady Wang's son Che, and Lady Wang agreed." },
  { zh: "由是長公主日讒栗姬而譽王夫人男之美；", literal: "therefore the Eldest Princess daily slandered Lady Li while praising the beauty of Lady Wang's son;", idiomatic: "thereafter the Eldest Princess daily slandered Lady Li while praising Lady Wang's son;" },
  { zh: "帝亦自賢之，又有曩者所夢日符，計未有所定。", literal: "the Emperor also himself considered him worthy, and again there was the former dream-sign of the sun—his deliberation had not yet been settled.", idiomatic: "the Emperor also considered him worthy himself, and again there was the earlier dream-sign of the sun—yet he had not decided." },
  { zh: "王夫人知帝嗛栗姬，因怒未解，陰使人趣大行請立栗姬為皇后。", literal: "Lady Wang knew the Emperor resented Lady Li and that his anger was not yet resolved; she secretly had someone urge the Grand Master of Ceremonies to request installing Lady Li as empress.", idiomatic: "Lady Wang knew the Emperor resented Lady Li and that his anger had not cooled; she secretly had someone urge the Grand Master of Ceremonies to request that Lady Li be made empress." },
  { zh: "帝怒曰：「是而所宜言邪！", literal: "The Emperor angrily said: \"Is this what you ought to speak!", idiomatic: "The Emperor angrily said, \"Is this what you ought to say!" },
  { zh: "」遂按誅大行。", literal: "\" He thereupon investigated and executed the Grand Master of Ceremonies.", idiomatic: "\" He thereupon investigated and executed the Grand Master of Ceremonies." },
  { zh: "----1冬，十一月，己酉，廢太子榮為臨江王。", literal: "----1 In winter, the eleventh month, on jiyou, the crown prince Rong was deposed and made King of Linjiang.", idiomatic: "----1 In winter, the eleventh month, on the day jiyou, Crown Prince Rong was deposed and made King of Linjiang." },
  { zh: "太子太傅竇嬰力爭不能得，乃謝病免。", literal: "Crown Prince Tutor Dou Ying strove in argument but could not prevail and thereupon pleaded illness and resigned.", idiomatic: "Crown Prince Tutor Dou Ying argued fiercely but could not prevail and thereupon pleaded illness and resigned." },
  { zh: "栗姬恚恨而死。", literal: "Lady Li died of resentment and hatred.", idiomatic: "Lady Li died of resentment and grief." },
  { zh: "----2庚寅晦，日有食之。", literal: "----2 On the last day gengyin, there was an eclipse of the sun.", idiomatic: "----2 On the last day gengyin, the sun was eclipsed." },
  { zh: "----3二月，丞相陶青免。", literal: "----3 In the second month, Chancellor Tao Qing was dismissed.", idiomatic: "----3 In the second month Chancellor Tao Qing was dismissed." },
  { zh: "乙巳，太尉周亞夫為丞相。", literal: "On yisi, Grand Commandant Zhou Yafu became Chancellor.", idiomatic: "On yisi Grand Commandant Zhou Yafu became chancellor." },
  { zh: "罷太尉官。", literal: "The office of Grand Commandant was abolished.", idiomatic: "The office of grand commandant was abolished." },
  { zh: "----4夏，四月，乙巳，立皇后王氏。", literal: "----4 In summer, the fourth month, on yisi, Lady Wang was installed as empress.", idiomatic: "----4 In summer, the fourth month, on yisi, Lady Wang was installed as empress." },
  { zh: "----5丁巳，立膠東王徹為皇太子。", literal: "----5 On dingsi, King Che of Jiaodong was installed as crown prince.", idiomatic: "----5 On dingsi King Che of Jiaodong was installed as crown prince." },
  { zh: "----6是歲，以太僕劉舍為御史大夫，濟南太守郅都為中尉。", literal: "----6 This year, Grand Master of the Palace Liu She was made Grandee Secretary and Administrator of Jinan Zhi Du was made Commandant of the Capital.", idiomatic: "----6 That year Grand Master of the Palace Liu She was made grandee secretary and Administrator of Jinan Zhi Du was made commandant of the capital." },
  { zh: "始，都為中郎將，敢直諫。", literal: "At the beginning, when Du was Central Palace General, he dared to remonstrate bluntly.", idiomatic: "Earlier, when Du was Central Palace General, he dared to remonstrate bluntly." },
  { zh: "嘗從入上林，賈姬如廁，野彘卒來入廁。", literal: "Once when he followed the Emperor into the Shanglin Park, Lady Jia went to the privy and a wild boar suddenly came in.", idiomatic: "Once when he followed the Emperor into the Shanglin Park, Lady Jia went to the privy and a wild boar suddenly burst in." },
  { zh: "上目都，都不行；", literal: "the Emperor signaled Du with his eyes, but neither moved;", idiomatic: "the Emperor signaled Du with his eyes, but neither moved;" },
  { zh: "上欲自持兵救賈姬。", literal: "the Emperor wished to take up arms himself to rescue Lady Jia.", idiomatic: "the Emperor wished to seize a weapon himself to rescue Lady Jia." },
  { zh: "都伏上前曰：「亡一姬，復一姬進，天下所少，寧賈姬等乎！", literal: "Du prostrated himself forward and said: \"Lose one lady and another enters—the realm lacks little; would Your Majesty value Lady Jia and the like!", idiomatic: "Du prostrated himself before the Emperor and said, \"Lose one lady and another takes her place—the realm lacks little; would Your Majesty risk yourself for Lady Jia!" },
  { zh: "陛下縱自輕，奈宗廟、太后何！", literal: "Your Majesty may lightly esteem yourself, but what of the ancestral temple and the Empress Dowager!", idiomatic: "Your Majesty may hold your own life cheap, but what of the ancestral temple and the empress dowager!" },
  { zh: "」上乃還，彘亦去。", literal: "\" The Emperor thereupon returned, and the boar also left.", idiomatic: "\" The Emperor thereupon withdrew, and the boar also left." },
  { zh: "太后聞之，賜都金百斤，由此重都。", literal: "When the Empress Dowager heard it she granted Du a hundred jin of gold; from this he was highly valued.", idiomatic: "When the empress dowager heard of it she granted Du a hundred jin of gold; from then on he was highly valued." },
  { zh: "都為人，勇悍公廉，不發私書，問遺無所受，請謁無所聽。", literal: "Du as a man was fierce, incorrupt, and public-minded; he sent no private letters, accepted no gifts in inquiry, and heard no private petitions.", idiomatic: "Du was fierce, upright, and incorrupt; he sent no private letters, accepted no gifts, and heard no private petitions." },
  { zh: "及為中尉，先嚴酷，行法不避貴戚。", literal: "When he became Commandant of the Capital, he was first severe and harsh, enforcing law without avoiding noble kin.", idiomatic: "As commandant of the capital he was first severe and harsh, enforcing the law without sparing noble kin." },
  { zh: "列侯、宗室見都，側目而視，號曰「蒼鷹」。", literal: "Ranked marquises and members of the imperial clan, seeing Du, looked sideways at him and called him \"Dark Hawk.\"", idiomatic: "Ranked marquises and imperial clansmen looked askance at him and called him \"Dark Hawk.\"" },
  { zh: "----1夏，四月，乙巳，赦天下。", literal: "----1 In summer, the fourth month, on yisi, he pardoned all under Heaven.", idiomatic: "----1 In summer, the fourth month, on yisi, he proclaimed a general amnesty." },
  { zh: "----2地震。", literal: "----2 There was an earthquake.", idiomatic: "----2 There was an earthquake." },
  { zh: "衡山原都雨雹，大者尺八寸。", literal: "At Yuandu in Hengshan hail fell as large as one foot eight inches.", idiomatic: "At Yuandu in Hengshan hail fell as large as one foot eight inches across." },
  { zh: "----1春，二月，匈奴入燕。", literal: "----1 In spring, the second month, the Xiongnu entered Yan.", idiomatic: "----1 In spring, the second month, the Xiongnu raided Yan." },
  { zh: "----2三月，臨江王榮坐侵太宗廟壖垣為宮，征詣中尉府對簿。", literal: "----2 In the third month, Prince Rong of Linjiang was charged with encroaching on the high founder's temple embankment to build a palace; he was summoned to the Commandant's office for trial.", idiomatic: "----2 In the third month Prince Rong of Linjiang was charged with encroaching on the high founder's temple embankment to build a palace and was summoned to the commandant's office for trial." },
  { zh: "臨江王欲得刀筆，為書謝上，而中尉郅都禁吏不予；", literal: "The Prince of Linjiang wished to obtain brush and knife to write a letter apologizing to the Emperor, but Commandant Zhi Du forbade the clerks to give them;", idiomatic: "Prince Rong of Linjiang wished to obtain brush and knife to write a letter of apology to the Emperor, but Commandant Zhi Du forbade the clerks to supply them;" },
  { zh: "魏其侯使人間與臨江王。", literal: "Marquis of Weiji sent a man secretly to communicate with the Prince of Linjiang.", idiomatic: "Marquis of Weiji sent a man secretly to communicate with Prince Rong of Linjiang." },
  { zh: "臨江王既為書謝上，因自殺。", literal: "Once the Prince of Linjiang had written the letter apologizing to the Emperor, he thereupon killed himself.", idiomatic: "Once Prince Rong had written his letter of apology to the Emperor, he killed himself." },
  { zh: "竇太后聞之，怒，後竟以危法中都而殺之。", literal: "When Empress Dowager Dou heard it she was angry; later she finally had Du killed by applying a dangerous law against him.", idiomatic: "When Empress Dowager Dou heard of it she was furious; later she had Du killed by applying a dangerous law against him." },
  { zh: "----3夏，四月，有星孛於西北。", literal: "----3 In summer, the fourth month, a broom star appeared in the northwest.", idiomatic: "----3 In summer, the fourth month, a comet appeared in the northwest." },
  { zh: "----4立皇子越為廣川王，寄為膠東王。", literal: "----4 The Emperor's sons Yue and Ji were installed as kings of Guangchuan and Jiaodong.", idiomatic: "----4 The Emperor's sons Yue and Ji were installed as kings of Guangchuan and Jiaodong." },
  { zh: "----5秋，九月，甲戌晦，日有食之。", literal: "----5 In autumn, the ninth month, on the last day jiaxu, there was an eclipse of the sun.", idiomatic: "----5 In autumn, the ninth month, on the last day jiaxu, the sun was eclipsed." },
  { zh: "----6初，梁孝王以至親有功，得賜天子旌旗。", literal: "----6 At the beginning, King Xiao of Liang, because he was a close kinsman with merit, was granted the Son of Heaven's banners and flags.", idiomatic: "----6 At first King Xiao of Liang, as a close kinsman with merit, was granted the Son of Heaven's banners and flags." },
  { zh: "從千乘萬騎，出蹕入警。", literal: "He went forth with a thousand chariots and ten thousand horsemen; when he exited the road was cleared and when he entered guards were posted.", idiomatic: "He went forth with a thousand chariots and ten thousand horsemen; when he went out the road was cleared and when he entered guards were posted." },
  { zh: "王寵信羊勝、公孫詭，以詭為中尉。", literal: "The king favored and trusted Yang Sheng and Gongsun Gui, making Gui his commandant.", idiomatic: "The king favored Yang Sheng and Gongsun Gui and made Gui his commandant." },
  { zh: "勝、詭多奇邪計，欲使王求為漢嗣。", literal: "Sheng and Gui had many strange and crooked schemes and wished to make the king seek to become heir to Han.", idiomatic: "Sheng and Gui devised many strange, crooked schemes and wished to make the king seek to become heir to Han." },
  { zh: "栗太子之廢也，太后意欲以梁王為嗣，嘗因置酒謂帝曰：「安車大駕，用梁王為寄。", literal: "When the Li crown prince was deposed, the Empress Dowager wished to make the King of Liang the heir; once at a feast she told the Emperor: \"The cushioned carriage and great escort—entrust them to the King of Liang.", idiomatic: "When Crown Prince Li was deposed the empress dowager wished to make the King of Liang the heir; once at a feast she told the Emperor, \"The cushioned carriage and great escort—entrust them to the King of Liang." },
  { zh: "」帝跪席舉身曰：「諾。", literal: "\" The Emperor knelt on the mat and raised his body, saying: \"Yes.", idiomatic: "\" The Emperor knelt on the mat and straightened up, saying, \"Yes." },
  { zh: "」罷酒，帝以訪諸大臣，大臣袁盎等曰：「不可。", literal: "\" When the wine was ended the Emperor consulted the great ministers; Minister Yuan Ang and others said: \"It cannot be done.", idiomatic: "\" When the feast ended the Emperor consulted the great ministers; Minister Yuan Ang and others said, \"It cannot be done." },
  { zh: "昔宋宣公不立子而立弟，以生禍亂，五世不絕。", literal: "Formerly Duke Xuan of Song did not install his son but installed his younger brother, thereby producing calamity and disorder that did not cease for five generations.", idiomatic: "Formerly Duke Xuan of Song did not install his son but installed his younger brother, thereby producing calamity and disorder that did not cease for five generations." },
  { zh: "小不忍，害大義，故《春秋》大居正。", literal: "Small impatience harms great principle—therefore the Spring and Autumn Annals greatly honors dwelling in the correct succession.", idiomatic: "Small impatience harms great principle—therefore the Spring and Autumn Annals greatly honors the rightful succession." },
  { zh: "」由是太后議格，遂不復言。", literal: "\" From this the Empress Dowager's deliberation was blocked, and she did not speak of it again.", idiomatic: "\" Thereupon the empress dowager's plan was blocked, and she spoke of it no more." },
  { zh: "王又嘗上書；", literal: "The king also once submitted a memorial;", idiomatic: "The king also once submitted a memorial:" },
  { zh: "「願賜容車之地，徑至長樂宮，自梁國士眾築作甬道朝太后。", literal: "\"I beg grant of land for a covered carriage route straight to Changle Palace, and that troops and people of Liang build a covered corridor-way to attend the Empress Dowager.", idiomatic: "\"I beg land for a covered carriage route straight to Changle Palace, and that Liang's troops and people build a covered corridor to attend the empress dowager." },
  { zh: "」袁盎等皆建以為不可。", literal: "\" Yuan Ang and the rest all advised that it could not be done.", idiomatic: "\" Yuan Ang and the rest all advised that it could not be done." },
  { zh: "梁王由此怨袁盎及議臣，乃與羊勝、公孫詭謀，陰使人刺殺袁盎及他議臣十餘人。", literal: "The King of Liang thereby resented Yuan Ang and the deliberating ministers; he then plotted with Yang Sheng and Gongsun Gui, secretly sending men to assassinate Yuan Ang and more than ten other deliberating ministers.", idiomatic: "The King of Liang thereby resented Yuan Ang and the ministers who had opposed him; he plotted with Yang Sheng and Gongsun Gui and secretly sent men to assassinate Yuan Ang and more than ten other opposing ministers." },
  { zh: "賊未得也，於是天子意梁；", literal: "The assassins had not yet been captured; the Son of Heaven thereupon suspected Liang;", idiomatic: "The assassins had not yet been caught, and the Son of Heaven thereupon suspected Liang;" },
  { zh: "逐賊，果梁所為。", literal: "when they pursued the assassins, it turned out to have been done by Liang.", idiomatic: "when the assassins were pursued, it proved to have been Liang's doing." },
  { zh: "上遣田叔、呂委主往按梁事，捕公孫詭、羊勝；", literal: "The Emperor sent Tian Shu and Lü Weizhu to go investigate the Liang affair and arrest Gongsun Gui and Yang Sheng;", idiomatic: "the Emperor sent Tian Shu and Lü Weizhu to investigate the Liang affair and arrest Gongsun Gui and Yang Sheng;" },
  { zh: "詭、勝匿王后宮，使者十餘輩至梁，責二千石急。", literal: "Gui and Sheng hid in the queen's inner palace; more than ten envoy parties reached Liang, urgently pressing the two-thousand-dan officials.", idiomatic: "Gui and Sheng hid in the queen's inner palace; more than ten envoy parties reached Liang and urgently pressed the two-thousand-dan officials." },
  { zh: "梁相軒丘豹及內史韓安國以下舉國大索，月餘弗得。", literal: "Liang Chancellor Xuanqiu Bao, Interior Minister Han Anguo, and those below mounted a nationwide search for more than a month without finding them.", idiomatic: "Liang Chancellor Xuanqiu Bao, Interior Minister Han Anguo, and the rest mounted a nationwide search for more than a month without finding them." },
  { zh: "安國聞詭、勝匿王所，乃入見王而泣曰：「主辱者臣死。", literal: "Anguo heard that Gui and Sheng were hiding at the king's place; he then entered to see the king and weeping said: \"When the lord is shamed, ministers die.", idiomatic: "Anguo heard that Gui and Sheng were hiding with the king; he entered to see the king and weeping said, \"When the lord is shamed, ministers die." },
  { zh: "大王無良臣，故紛紛至此。", literal: "Your Majesty has no good ministers—hence things have come to such disorder.", idiomatic: "Your Majesty has no good ministers, and so things have come to such disorder." },
  { zh: "今勝、詭不得，請辭，賜死！", literal: "Now that Sheng and Gui cannot be found, I request to resign—grant me death!", idiomatic: "Now that Sheng and Gui cannot be found, I beg to resign—grant me death!" },
  { zh: "」王曰：「何至此！", literal: "\" The king said: \"How reach such a point!", idiomatic: "\" The king said, \"How could it come to this!" },
  { zh: "」安國泣數行下，曰：「大王自度於皇帝，孰與臨江王親？", literal: "\" Anguo weeping several lines of tears, said: \"Your Majesty, judge yourself against the Emperor—who is closer, you or the King of Linjiang?", idiomatic: "\" Anguo wept freely and said, \"Your Majesty, judge yourself against the Emperor—which of you is closer to him, you or the King of Linjiang?" },
  { zh: "」王曰：「弗如也。", literal: "\" The king said: \"I am not as close.", idiomatic: "\" The king said, \"I am not as close." },
  { zh: "」安國曰：「臨江王鱣長太子，以一言過，廢王臨江；", literal: "\" Anguo said: \"The King of Linjiang was the grown crown prince; for a single fault of speech he was deposed and made king of Linjiang;", idiomatic: "\" Anguo said, \"The King of Linjiang was the grown crown prince; for a single fault of speech he was deposed and made king of Linjiang;" },
  { zh: "用宮垣事，卒自殺中尉府。", literal: "over the palace rampart affair he finally killed himself at the Commandant's office.", idiomatic: "over the palace rampart affair he finally killed himself at the commandant's office." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "治天下終不用私亂公。", literal: "Governing all under Heaven ultimately does not use private ties to disorder public law.", idiomatic: "Governing the realm ultimately does not let private ties disorder public law." },
  { zh: "今大王列在諸侯，訹邪臣浮說，犯上禁，橈明法。", literal: "Now Your Majesty ranks among the feudal lords; vicious evil ministers make floating speeches, violating superior prohibitions and bending clear law.", idiomatic: "Now Your Majesty ranks among the feudal lords; vicious ministers spread reckless talk, violate imperial prohibitions, and bend clear law." },
  { zh: "天子以太后故，不忍致法於大王；", literal: "The Son of Heaven because of the Empress Dowager cannot bear to apply the law to Your Majesty;", idiomatic: "the Son of Heaven, because of the empress dowager, cannot bear to apply the law to Your Majesty;" },
  { zh: "太后日夜涕泣，幸大王自改，大王終不覺寤。", literal: "the Empress Dowager day and night weeps tears, hoping Your Majesty will reform yourself—Your Majesty ultimately does not awaken.", idiomatic: "the empress dowager weeps day and night, hoping Your Majesty will reform yourself—yet Your Majesty never awakens to it." },
  { zh: "有如太后宮車即晏駕，大王尚誰攀乎？", literal: "Should the Empress Dowager's palace carriage soon reach evening departure, whom would Your Majesty still cling to?", idiomatic: "Should the empress dowager's palace carriage soon depart on its final journey, whom would Your Majesty still have to cling to?" },
  { zh: "」語未卒，王泣數行而下，謝安國曰：「吾今出勝、詭。", literal: "\" Before the words were finished the king wept several lines of tears and said in apology to Anguo: \"I will now hand over Sheng and Gui.", idiomatic: "\" Before he finished speaking the king wept freely and apologized to Anguo, \"I will now hand over Sheng and Gui." },
  { zh: "」王乃令勝、詭皆自殺，出之。", literal: "\" The king then ordered Sheng and Gui both to kill themselves and handed them over.", idiomatic: "\" The king then ordered Sheng and Gui both to kill themselves and handed their bodies over." },
  { zh: "上由此怨望梁王。", literal: "The Emperor thereby bore resentment toward the King of Liang.", idiomatic: "The Emperor thereby bore resentment toward the King of Liang." },
  { zh: "梁王恐，使鄒陽入長安，見皇后兄王信說曰：「長君弟得幸於上，後宮莫及；", literal: "The King of Liang was afraid; he sent Zou Yang into Chang'an to see the Empress's elder brother Wang Xin and persuade him, saying: \"Chief Excellency, your younger sister is favored by the Emperor—none in the inner palace can match her;", idiomatic: "The King of Liang was afraid; he sent Zou Yang into Chang'an to see the empress's elder brother Wang Xin and said, \"Chief Excellency, your younger sister is favored by the Emperor—none in the inner palace can match her;" },
  { zh: "而長君行跡多不循道理者。", literal: "yet Chief Excellency, your conduct often does not follow reason.", idiomatic: "yet Chief Excellency, your conduct often does not follow reason." },
  { zh: "今袁盎事即究竟，梁王伏誅，太后無所發怒，切齒側目於貴臣，竊為足下憂之。", literal: "Now that the Yuan Ang affair is about to be concluded, the King of Liang will submit to execution; the Empress Dowager will have nowhere to vent her anger—she will gnash teeth and look askance at noble ministers; I privately worry for you.", idiomatic: "Now that the Yuan Ang affair is about to be concluded, the King of Liang will submit to execution; the empress dowager will have nowhere to vent her anger and will gnash her teeth and look askance at noble ministers—I privately worry for you." },
  { zh: "」長君曰：「為之奈何？", literal: "\" Chief Excellency said: \"What is to be done about it?", idiomatic: "\" Chief Excellency said, \"What is to be done about it?" },
  { zh: "」陽曰：「長君誠能精為上言之，得毋竟梁事；", literal: "\" Yang said: \"If Chief Excellency can truly speak to the Emperor with care, the Liang affair may not be concluded;", idiomatic: "\" Yang said, \"If Chief Excellency can truly speak carefully to the Emperor, the Liang affair may not be concluded;" },
  { zh: "長君必固自結於太后，太后厚德長君入於骨髓，而長君之弟幸於兩宮，金城之固也。", literal: "Chief Excellency will surely firmly bind himself to the Empress Dowager; the Empress Dowager's deep virtue toward Chief Excellency will enter to the marrow, and Chief Excellency's younger sister is favored in both palaces—a solidity like a metal city wall.", idiomatic: "Chief Excellency will surely bind himself firmly to the empress dowager; her deep favor toward you will enter to the marrow, and your younger sister is favored in both palaces—a solidity like walls of bronze." },
  { zh: "昔者舜之弟象，日以殺舜為事，及舜立為天子，封之於有卑。", literal: "Formerly Shun's younger brother Xiang daily made killing Shun his business; when Shun was installed as Son of Heaven he enfeoffed him at Youbei.", idiomatic: "Formerly Shun's younger brother Xiang daily made killing Shun his business; when Shun was installed as Son of Heaven he enfeoffed him at Youbei." },
  { zh: "夫仁人之于兄弟，無藏怒，無宿怨，厚親愛而已。", literal: "For benevolent men toward brothers: no hidden anger, no stored resentment—only thick kin-love.", idiomatic: "For benevolent men toward brothers there is no hidden anger and no stored resentment—only deep kin-love." },
  { zh: "是以後世稱之。", literal: "Therefore later ages praise him.", idiomatic: "Therefore later ages praise him." },
  { zh: "以是說天子，徼幸梁事不奏。", literal: "Use this to persuade the Son of Heaven, hoping perchance the Liang affair will not be reported.", idiomatic: "Use this to persuade the Son of Heaven, hoping perchance the Liang affair will not be reported." },
  { zh: "」長君曰：「諾。", literal: "\" Chief Excellency said: \"Agreed.", idiomatic: "\" Chief Excellency said, \"Agreed." },
  { zh: "」乘間入言之。", literal: "\" Seizing an interval he entered and spoke it.", idiomatic: "\" Seizing an opportunity he entered and spoke to the Emperor." },
  { zh: "帝怒稍解。", literal: "The Emperor's anger gradually eased.", idiomatic: "The Emperor's anger gradually eased." },
  { zh: "是時，太后憂梁事不食，日夜泣不止，帝亦患之。", literal: "At this time the Empress Dowager, distressed over the Liang affair, would not eat and wept day and night without cease; the Emperor also was troubled.", idiomatic: "At this time the empress dowager, distressed over the Liang affair, would not eat and wept day and night without cease; the Emperor was troubled as well." },
  { zh: "會田叔等按梁事來還，至霸昌廄，取火悉燒梁之獄辭，空手來見帝。", literal: "When Tian Shu and the rest investigating the Liang affair came back, at Bachang Stable they took fire and burned all of Liang's prison records entirely, and came empty-handed to see the Emperor.", idiomatic: "When Tian Shu and the rest investigating the Liang affair returned, at Bachang Stable they took fire and burned all of Liang's case records, then came empty-handed to see the Emperor." },
  { zh: "帝曰：「梁有之乎？", literal: "The Emperor said: \"Did Liang have involvement?", idiomatic: "The Emperor said, \"Did Liang have involvement?" },
  { zh: "」叔對曰：「死罪。", literal: "\" Shu replied: \"A capital offense.", idiomatic: "\" Shu replied, \"A capital offense." },
  { zh: "有之。", literal: "There was.", idiomatic: "There was." },
  { zh: "」上曰：「其事安在？", literal: "\" The Emperor said: \"Where is the matter?", idiomatic: "\" The Emperor said, \"Where is the evidence?" },
  { zh: "」田叔曰：「上毋以梁事為問也。", literal: "\" Tian Shu said: \"Your Majesty, do not ask about the Liang affair.", idiomatic: "\" Tian Shu said, \"Your Majesty, do not ask about the Liang affair." },
  { zh: "」上曰：「何也？", literal: "\" The Emperor said: \"Why?", idiomatic: "\" The Emperor said, \"Why?" },
  { zh: "」曰：「今梁王不伏誅，是漢法不行也；", literal: "\" He said: \"Now if the King of Liang does not submit to execution, Han law is not enforced;", idiomatic: "\" He said, \"Now if the King of Liang does not submit to execution, Han law is not enforced;" },
  { zh: "伏法而太后食不甘味，臥不安席，此憂在陛下也。", literal: "if he submits to the law the Empress Dowager will find food not sweet and sleep not restful on her mat—this worry rests on Your Majesty.", idiomatic: "if he submits to the law the empress dowager will find no pleasure in food and no rest on her mat—this worry rests on Your Majesty." },
  { zh: "」上大然之，使叔等謁太后，且曰：「梁王不知也。", literal: "\" The Emperor greatly approved; he had Shu and the rest call on the Empress Dowager, saying moreover: \"The King of Liang did not know.", idiomatic: "\" The Emperor greatly approved; he had Shu and the rest call on the empress dowager, saying moreover, \"The King of Liang did not know." },
  { zh: "造為之者，獨在幸臣羊勝、公孫詭之屬為之耳，謹已伏誅死，梁王無恙也。", literal: "What was made was solely done by the favored ministers Yang Sheng, Gongsun Gui, and their sort; they have respectfully submitted to execution and died—the King of Liang is unharmed.", idiomatic: "What was done was solely the work of the favored ministers Yang Sheng, Gongsun Gui, and their sort; they have respectfully been executed and died—the King of Liang is unharmed." },
  { zh: "」太后聞之，立起坐餐，氣平復。", literal: "\" When the Empress Dowager heard it she immediately rose and sat to eat; her breath calmed and she recovered.", idiomatic: "\" When the empress dowager heard it she immediately rose and sat down to eat; her breath calmed and she recovered." },
  { zh: "梁王因上書請朝。", literal: "The King of Liang thereupon submitted a memorial requesting court attendance.", idiomatic: "The King of Liang thereupon submitted a memorial requesting an audience at court." },
  { zh: "既至關，茅蘭說王，使乘布車，從兩騎入，匿於長公主園。", literal: "When he reached the pass, Mao Lan persuaded the king to ride a cloth-covered carriage with two riders following, enter, and hide in the Eldest Princess's garden.", idiomatic: "When he reached the pass, Mao Lan persuaded the king to ride a plain cloth carriage with only two riders, enter, and hide in the Eldest Princess's garden." },
  { zh: "漢使使迎王，王已入關，車騎盡居外，不知王處。", literal: "Han sent envoys to welcome the king; the king had already entered the pass—chariots and horsemen all remained outside, not knowing where the king was.", idiomatic: "Han sent envoys to welcome the king; the king had already entered the pass while his chariots and horsemen all remained outside, not knowing where he was." },
  { zh: "太后泣曰：「帝果殺吾子！", literal: "The Empress Dowager wept: \"The Emperor has truly killed my son!", idiomatic: "The empress dowager wept, \"The Emperor has truly killed my son!" },
  { zh: "」帝憂恐。", literal: "\" The Emperor was anxious and afraid.", idiomatic: "\" The Emperor was anxious and afraid." },
  { zh: "於是梁王伏斧質於闕下謝罪。", literal: "Thereupon the King of Liang prostrated himself with axe and block beneath the palace gate to apologize.", idiomatic: "Thereupon the King of Liang prostrated himself with axe and block beneath the palace gate to beg forgiveness." },
  { zh: "太后、帝大喜，相泣，復如故，悉召王從官入關。", literal: "The Empress Dowager and Emperor were greatly pleased, wept toward each other, were restored as before, and summoned all the king's attendants to enter the pass.", idiomatic: "The empress dowager and Emperor were greatly pleased, wept toward each other, were restored as before, and summoned all the king's attendants to enter the pass." },
  { zh: "然帝益疏王，不與同車輦矣。", literal: "Yet the Emperor increasingly kept the king at a distance and did not ride in the same carriage with him.", idiomatic: "Yet the Emperor increasingly kept the king at a distance and no longer rode in the same carriage with him." },
  { zh: "帝以田叔為賢，擢為魯相。", literal: "The Emperor took Tian Shu to be worthy and promoted him to Chancellor of Lu.", idiomatic: "The Emperor judged Tian Shu worthy and promoted him to chancellor of Lu." },
  { zh: "----1冬，十一月，罷諸侯御史大夫官。", literal: "----1 In winter, the eleventh month, the office of Grandee Secretary among the feudal lords was abolished.", idiomatic: "----1 In winter, the eleventh month, the office of grandee secretary among the feudal lords was abolished." },
  { zh: "----2夏，四月，地震。", literal: "----2 In summer, the fourth month, there was an earthquake.", idiomatic: "----2 In summer, the fourth month, there was an earthquake." },
  { zh: "----3旱，禁酤酒。", literal: "----3 In drought, the sale of wine was forbidden.", idiomatic: "----3 In drought, the sale of wine was forbidden." },
  { zh: "----4三月，丁巳，立皇子乘為清河王。", literal: "----4 In the third month, on dingsi, the Emperor's son Cheng was installed as King of Qinghe.", idiomatic: "----4 In the third month, on dingsi, the Emperor's son Cheng was installed as King of Qinghe." },
  { zh: "----5秋，九月，蝗。", literal: "----5 In autumn, the ninth month, there were locusts.", idiomatic: "----5 In autumn, the ninth month, locusts appeared." },
  { zh: "----6有星孛於西北。", literal: "----6 A broom star appeared in the northwest.", idiomatic: "----6 A comet appeared in the northwest." },
  { zh: "----7戊戌晦，日有食之。", literal: "----7 On the last day wuxu, there was an eclipse of the sun.", idiomatic: "----7 On the last day wuxu, the sun was eclipsed." },
  { zh: "----8初，上廢栗太子，周亞夫固爭之，不得；", literal: "----8 At the beginning, when the Emperor deposed the Li crown prince, Zhou Yafu strove in argument but could not prevail;", idiomatic: "----8 At first, when the Emperor deposed Crown Prince Li, Zhou Yafu argued fiercely but could not prevail;" },
  { zh: "上由此疏之。", literal: "the Emperor thereby kept him at a distance.", idiomatic: "the Emperor thereby kept him at a distance." },
  { zh: "而梁孝王每朝，常與太后言條侯之短。", literal: "Yet King Xiao of Liang, whenever he attended court, often spoke to the Empress Dowager of Marquis of Tiao's faults.", idiomatic: "Yet whenever King Xiao of Liang attended court he often told the empress dowager of Marquis of Tiao's faults." },
  { zh: "竇太后曰：「皇后兄王信可侯也。", literal: "Empress Dowager Dou said: \"The Empress's elder brother Wang Xin may be ennobled.", idiomatic: "Empress Dowager Dou said, \"The empress's elder brother Wang Xin may be ennobled." },
  { zh: "」帝讓曰：「始，南皮、章武，先帝不侯，及臣即位乃侯之；", literal: "\" The Emperor remonstrated: \"At first Nanpi and Zhangwu—the late Emperor did not ennoble them; only when your servant took the throne were they ennobled;", idiomatic: "\" The Emperor objected, \"At first Nanpi and Zhangwu—the late Emperor did not ennoble them; only when I took the throne were they ennobled;" },
  { zh: "信未得封也。", literal: "Xin has not yet received a fief.", idiomatic: "Xin has not yet received a fief." },
  { zh: "」竇太后曰：「人生各以時行耳。", literal: "\" Empress Dowager Dou said: \"In life each acts according to his time.", idiomatic: "\" Empress Dowager Dou said, \"In life each acts according to his time." },
  { zh: "自竇長君在時，竟不得侯，死後，其子彭祖顧得侯，吾甚恨之！", literal: "When Chief Dou was alive he ultimately could not be ennobled; after death his son Pengzu alone was ennobled—I deeply resent it!", idiomatic: "When Chief Dou was alive he ultimately could not be ennobled; after his death only his son Pengzu was ennobled—I deeply resent it!" },
  { zh: "帝趣侯信也。", literal: "Your Majesty, hasten to ennoble Xin.", idiomatic: "Your Majesty, hasten to ennoble Xin." },
  { zh: "」帝曰：「請得與丞相議之。", literal: "\" The Emperor said: \"I beg leave to deliberate with the Chancellor.", idiomatic: "\" The Emperor said, \"Let me deliberate with the chancellor." },
  { zh: "上與丞相議。", literal: "The Emperor deliberated with the Chancellor.", idiomatic: "The Emperor deliberated with the chancellor." },
  { zh: "亞夫曰：「高皇帝約：『非劉氏不得王，非有功不得侯。", literal: "Yafu said: \"The High Emperor's covenant: 'None but the Liu clan may be king; none without merit may be ennobled.", idiomatic: "Yafu said, \"The High Emperor's covenant: 'None but the Liu clan may be king; none without merit may be ennobled." },
  { zh: "』今信雖皇后兄，無功，侯之，非約也。", literal: "' Now though Xin is the Empress's elder brother, without merit—to ennoble him is not the covenant.", idiomatic: "' Now though Xin is the empress's elder brother, without merit—to ennoble him violates the covenant." },
  { zh: "」帝默然而止。", literal: "\" The Emperor fell silent and stopped.", idiomatic: "\" The Emperor fell silent and dropped the matter." },
  { zh: "其後匈奴王徐廬等六人降，帝欲侯之以勸後。", literal: "Afterward the Xiongnu kings Xu Lu and five others surrendered; the Emperor wished to ennoble them to encourage those who followed.", idiomatic: "Afterward the Xiongnu kings Xu Lu and five others surrendered; the Emperor wished to ennoble them to encourage future defectors." },
  { zh: "丞相亞夫曰：「彼背主降陛下，陛下侯之，則何以責人臣不守節者乎？", literal: "Chancellor Yafu said: \"They betrayed their lord and surrendered to Your Majesty—if Your Majesty ennobles them, how will you reproach subjects who do not hold to their integrity?", idiomatic: "Chancellor Yafu said, \"They betrayed their lord and surrendered to Your Majesty—if Your Majesty ennobles them, how will you reproach subjects who fail to hold to their integrity?" },
  { zh: "」帝曰：「丞相議不可用。", literal: "\" The Emperor said: \"The Chancellor's deliberation cannot be used.", idiomatic: "\" The Emperor said, \"The chancellor's advice cannot be followed." },
  { zh: "」乃悉封徐廬等為列侯。", literal: "\" He thereupon ennobled Xu Lu and the rest all as ranked marquises.", idiomatic: "\" He thereupon ennobled Xu Lu and the rest all as ranked marquises." },
  { zh: "亞夫因謝病。", literal: "Yafu thereupon pleaded illness.", idiomatic: "Yafu thereupon pleaded illness and resigned." },
  { zh: "九月，戊戌，亞夫免；", literal: "In the ninth month, on wuxu, Yafu was dismissed;", idiomatic: "In the ninth month, on wuxu, Yafu was dismissed;" },
  { zh: "以御史大夫桃侯劉舍為丞相。", literal: "Grandee Secretary Marquis of Tao Liu She was made Chancellor.", idiomatic: "Grandee Secretary Marquis of Tao Liu She was made chancellor." },
  { zh: "----1夏，蝗。", literal: "----1 In summer, there were locusts.", idiomatic: "----1 In summer, locusts appeared." },
  { zh: "----2冬，十月，戊午，日有食之。", literal: "----2 In winter, the tenth month, on wuwu, there was an eclipse of the sun.", idiomatic: "----2 In winter, the tenth month, on wuwu, the sun was eclipsed." },
  { zh: "----1夏，立皇子舜為常山王。", literal: "----1 In summer, the Emperor's son Shun was installed as King of Changshan.", idiomatic: "----1 In summer, the Emperor's son Shun was installed as King of Changshan." },
  { zh: "----2六月，丁巳，赦天下。", literal: "----2 In the sixth month, on dingsi, he pardoned all under Heaven.", idiomatic: "----2 In the sixth month, on dingsi, he proclaimed a general amnesty." },
  { zh: "----3大水。", literal: "----3 There were great floods.", idiomatic: "----3 There were great floods." },
  { zh: "----4秋，八月，己酉，未央宮東闕災。", literal: "----4 In autumn, the eighth month, on jiyou, the eastern gate-tower of Weiyang Palace caught fire.", idiomatic: "----4 In autumn, the eighth month, on jiyou, the eastern gate-tower of Weiyang Palace caught fire." },
  { zh: "----5九月，詔：「諸獄疑，若雖文致於法，而於人心不厭者，輒讞之。", literal: "----5 In the ninth month, an edict: \"In all doubtful prison cases, if though the letter of the law is applied the hearts of men are not satisfied, report them at once.", idiomatic: "----5 In the ninth month, an edict ran: \"In all doubtful prison cases, if though the letter of the law is applied the hearts of men are not satisfied, report them at once." },
  { zh: "」----6地震。", literal: "\" ----6 There was an earthquake.", idiomatic: "\" ----6 There was an earthquake." },
  { zh: "----1冬，十月，梁王來朝，上疏欲留；", literal: "----1 In winter, the tenth month, the King of Liang came to court and submitted a memorial wishing to stay;", idiomatic: "----1 In winter, the tenth month, the King of Liang came to court and submitted a memorial wishing to remain;" },
  { zh: "上弗許。", literal: "the Emperor did not permit it.", idiomatic: "the Emperor did not permit it." },
  { zh: "王歸國，意忽忽不樂。", literal: "The king returned to his state, his mood listless and unhappy.", idiomatic: "The king returned to his state listless and unhappy." },
  { zh: "----2十二月，改諸廷尉、將作等官名。", literal: "----2 In the twelfth month, the names of the Commandant of Justice, Director of Palace Construction, and other offices were changed.", idiomatic: "----2 In the twelfth month, the names of the commandant of justice, director of palace construction, and other offices were changed." },
  { zh: "----3春，二月，乙卯，上行幸雍，郊五畤。", literal: "----3 In spring, the second month, on yimao, the Emperor traveled in person to Yong and sacrificed at the Five Altars.", idiomatic: "----3 In spring, the second month, on yimao, the Emperor traveled in person to Yong and sacrificed at the Five Altars." },
  { zh: "----4三月，雨雪。", literal: "----4 In the third month, there was snow and rain.", idiomatic: "----4 In the third month, there was snow and rain." },
  { zh: "----5夏，四月，梁孝王薨。", literal: "----5 In summer, the fourth month, King Xiao of Liang died.", idiomatic: "----5 In summer, the fourth month, King Xiao of Liang died." },
  { zh: "竇太后聞之，哭極哀，不食，曰：「帝果殺吾子！", literal: "Empress Dowager Dou heard it, wept with extreme grief, would not eat, and said: \"The Emperor indeed killed my son!", idiomatic: "When Empress Dowager Dou heard it she wept with extreme grief and would not eat, saying, \"The Emperor has indeed killed my son!" },
  { zh: "」帝哀懼，不知所為；", literal: "\" The Emperor was sorrowful and afraid, not knowing what to do;", idiomatic: "\" The Emperor was grief-stricken and afraid, not knowing what to do;" },
  { zh: "與長公主計之，乃分梁為五國，盡立孝王男五人為王：買為梁王，明為濟川王，彭離為濟東王，定為山陽王，不識為濟陰王；", literal: "He consulted with the Eldest Princess, then divided Liang into five states and installed all five sons of King Xiao as kings: Mai as King of Liang, Ming as King of Jichuan, Pengli as King of Jidong, Ding as King of Shanyang, Bushi as King of Jiyin;", idiomatic: "He took counsel with the Eldest Princess, divided Liang into five states, and installed all five of King Xiao's sons as kings: Mai as King of Liang, Ming as King of Jichuan, Pengli as King of Jidong, Ding as King of Shanyang, and Bushi as King of Jiyin;" },
  { zh: "女五人皆食湯沐邑。", literal: "the five daughters all received fief income from bath towns.", idiomatic: "his five daughters all received bath-town fiefs for their upkeep." },
  { zh: "奏之太后，太后乃說，為帝加一餐。", literal: "He reported this to the Empress Dowager; the Empress Dowager was then pleased and added one meal for the Emperor.", idiomatic: "He reported this to the empress dowager; she was pleased and took a meal again, adding one for the Emperor as well." },
  { zh: "孝王未死時，財以巨萬計，及死，藏府餘黃金尚四十餘萬斤。", literal: "Before King Xiao died his wealth was reckoned in tens of thousands; when he died, what remained in the treasury stores was still more than four hundred thousand jin of gold.", idiomatic: "Before King Xiao died his wealth was reckoned in the tens of thousands; at his death the treasury still held more than four hundred thousand jin of gold." },
  { zh: "他物稱是。", literal: "Other goods matched this.", idiomatic: "Other goods were proportionate." },
  { zh: "----6上既減笞法，笞者猶不全；", literal: "----6 After the Emperor had reduced the flogging law, those flogged still did not survive intact;", idiomatic: "----6 After the Emperor had reduced the flogging statutes, those flogged still did not survive whole;" },
  { zh: "乃更減笞三百曰二百，笞二百曰一百。", literal: "he then further reduced three hundred strokes to two hundred, and two hundred to one hundred.", idiomatic: "he further reduced three hundred strokes to two hundred and two hundred to one hundred." },
  { zh: "又定棰令：棰長五尺，其本大一寸，竹也；", literal: "He also fixed the cudgel statute: the cudgel was five feet long, its butt one inch thick, of bamboo;", idiomatic: "He also fixed the cudgel rules: the cudgel was five feet long, one inch thick at the butt, and of bamboo;" },
  { zh: "末薄半寸，皆平其節。", literal: "the tip thin by half an inch, and all nodes smoothed flat.", idiomatic: "the tip thinned to half an inch, with all nodes smoothed flat." },
  { zh: "當笞得笞臀；", literal: "When flogging was due, the buttocks were to be flogged;", idiomatic: "when flogging was due the buttocks were to be struck;" },
  { zh: "畢一罪，乃更人。", literal: "when one offense was finished, the flogger was changed.", idiomatic: "when one offense was finished the flogger was changed." },
  { zh: "自是笞者得全。", literal: "From this those flogged survived whole.", idiomatic: "From then on those flogged survived intact." },
  { zh: "然死刑既重而生刑又輕，民易犯之。", literal: "Yet the death penalty was already heavy while the living punishments were again light, and the people easily offended.", idiomatic: "Yet the death penalty remained heavy while corporal punishments were light again, and the people offended the law easily." },
  { zh: "----7六月，匈奴入雁門，至武泉，入上郡，取苑馬。", literal: "----7 In the sixth month, the Xiongnu entered Yanmen, reached Wuquan, entered Shang commandery, and took park horses.", idiomatic: "----7 In the sixth month the Xiongnu entered Yanmen, reached Wuquan, entered Shang commandery, and seized the imperial park horses." },
  { zh: "吏卒戰死者二千人。", literal: "Officials and soldiers who died in battle numbered two thousand.", idiomatic: "Two thousand officials and soldiers died in battle." },
  { zh: "隴西李廣為上郡太守，嘗從百騎出，卒遇匈奴數千騎。", literal: "Li Guang of Longxi was Administrator of Shang commandery; once he went out with a hundred horsemen and suddenly encountered several thousand Xiongnu horsemen.", idiomatic: "Li Guang of Longxi was administrator of Shang commandery; once he went out with a hundred horsemen and suddenly met several thousand Xiongnu horsemen." },
  { zh: "見廣，以為誘騎，皆驚，上山陳。", literal: "Seeing Guang, they took him for decoy horsemen; all were alarmed and went up the hill to form battle order.", idiomatic: "Seeing Guang they took him for a decoy force; all were alarmed and went up a hill to form ranks." },
  { zh: "廣之百騎皆大恐，欲馳還走。", literal: "Guang's hundred horsemen were all greatly afraid and wished to gallop back and flee.", idiomatic: "Guang's hundred horsemen were terrified and wished to gallop back and flee." },
  { zh: "廣曰：「吾去大軍數十里，今如此以百騎走，匈奴追射我立盡。", literal: "Guang said: \"We are several tens of li from the main army; if now we flee thus with a hundred horsemen, the Xiongnu will pursue and shoot us and we will be wiped out at once.", idiomatic: "Guang said, \"We are several tens of li from the main army; if we flee now with only a hundred horsemen the Xiongnu will pursue and shoot us down at once." },
  { zh: "今我留，匈奴必以我為大軍之誘，必不敢擊我。", literal: "If we stay now, the Xiongnu will surely take us for the main army's decoy and will surely not dare attack us.", idiomatic: "If we stay the Xiongnu will surely take us for the main army's decoy and will not dare attack." },
  { zh: "」廣令諸騎曰：「前！", literal: "\" Guang ordered the horsemen: \"Forward!", idiomatic: "\" Guang ordered the horsemen, \"Forward!" },
  { zh: "」未到匈奴陣二里所，止，令曰：「皆下馬解鞍！", literal: "\" Before reaching the Xiongnu battle line by about two li, he halted and ordered: \"All dismount and unbuckle the saddles!", idiomatic: "\" Before they had come within about two li of the Xiongnu line he halted and ordered, \"All dismount and unbuckle your saddles!" },
  { zh: "」其騎曰：「虜多且近，即有急，奈何？", literal: "\" His horsemen said: \"The enemy are many and near; if there is sudden danger, what then?", idiomatic: "\" His men said, \"The enemy are many and close; if trouble comes, what then?" },
  { zh: "」廣曰：「彼虜以我為走；", literal: "\" Guang said: \"Those barbarians take us for fleeing;", idiomatic: "\" Guang said, \"Those barbarians take us for fleeing;" },
  { zh: "今皆解鞍以示不走，用堅其意。", literal: "now if all unbuckle saddles to show we are not fleeing, we will fix their belief.", idiomatic: "now if we all unbuckle our saddles to show we are not fleeing we will fix their belief." },
  { zh: "」於是胡騎遂不敢擊。", literal: "\" Thereupon the barbarian horsemen did not dare attack.", idiomatic: "\" Thereupon the Xiongnu horsemen did not dare attack." },
  { zh: "有白馬將出，護其兵；", literal: "A white-horse general came out to protect his troops;", idiomatic: "A white-horse general came out to protect his troops;" },
  { zh: "李廣上馬，與十餘騎奔，射殺白馬將而復還，至其騎中解鞍，令士皆縱馬臥。", literal: "Li Guang mounted, and with more than ten horsemen charged, shot and killed the white-horse general, then returned again; reaching his horsemen he unbuckled saddles and ordered the men all to let their horses roam and lie down.", idiomatic: "Li Guang mounted and with more than ten horsemen charged, shot and killed the white-horse general, then returned; reaching his men he unbuckled saddles again and ordered them to let their horses roam and lie down." },
  { zh: "是時會暮，胡兵終怪之，不敢擊。", literal: "At this time dusk fell; the barbarian troops still found it strange and did not dare attack.", idiomatic: "By then it was dusk; the Xiongnu troops still found it strange and did not dare attack." },
  { zh: "夜半時，胡兵亦以為漢有伏軍於旁，欲夜取之，胡皆引兵而去。", literal: "At midnight the barbarian troops also thought Han had ambush troops nearby and wished to take them by night; the barbarians all led their troops away.", idiomatic: "At midnight the Xiongnu also thought Han had ambush troops nearby and meant to strike by night; they all withdrew." },
  { zh: "平旦，李廣乃歸其大軍。", literal: "At daybreak Li Guang then returned to his main army.", idiomatic: "At daybreak Li Guang rejoined his main army." },
  { zh: "----8秋，七月，辛亥晦，日有食之。", literal: "----8 In autumn, the seventh month, on the last day xinhai, there was an eclipse of the sun.", idiomatic: "----8 In autumn, the seventh month, on the last day xinhai, the sun was eclipsed." },
  { zh: "----9自郅都之死，長安左右宗室多暴犯法。", literal: "----9 From the death of Zhi Du, the imperial clansmen around Chang'an mostly committed violent offenses against the law.", idiomatic: "----9 After Zhi Du's death the imperial clansmen around Chang'an mostly committed violent offenses." },
  { zh: "上乃召濟南都尉南陽寧成為中尉。", literal: "The Emperor thereupon summoned Commandant of Jinan Ning Cheng of Nanyang to be Commandant of the Capital.", idiomatic: "The Emperor thereupon summoned Commandant of Jinan Ning Cheng of Nanyang to be commandant of the capital." },
  { zh: "其治效郅都，其廉弗如。", literal: "His governance matched Zhi Du's effect; his integrity did not equal his.", idiomatic: "His governance matched Zhi Du's effectiveness, but his integrity did not." },
  { zh: "然宗室、豪桀皆人人惴恐。", literal: "Yet the imperial clan and powerful men were each and all fearful and trembling.", idiomatic: "Yet every man of the imperial clan and the powerful houses trembled in fear." },
  { zh: "----10城陽共王喜薨。", literal: "----10 Duke King Xi of Chengyang died.", idiomatic: "----10 Duke King Xi of Chengyang died." },
  { zh: "----1春，正月，詔曰：「獄，重事也。", literal: "----1 In spring, the first month, an edict said: \"Prisons are weighty affairs.", idiomatic: "----1 In spring, the first month, an edict ran: \"Prisons are grave affairs." },
  { zh: "人有智愚，官有上下。", literal: "Men have wisdom and folly; offices have high and low.", idiomatic: "Men differ in wisdom and folly; offices differ in rank." },
  { zh: "獄疑者讞有司；", literal: "When a prison case is doubtful, report to the relevant offices;", idiomatic: "doubtful prison cases are to be reported to the relevant offices;" },
  { zh: "有司所不能決，移廷尉；", literal: "what the relevant offices cannot decide is transferred to the Court Commandant;", idiomatic: "what those offices cannot decide is transferred to the Court Commandant;" },
  { zh: "讞而後不當，讞後不為失。", literal: "if after reporting the decision is not correct, the reporting afterward is not counted as fault.", idiomatic: "if after reporting the decision proves wrong, the reporter is not held at fault." },
  { zh: "欲令治獄者務先寬。", literal: "I wish those who handle prisons to strive first for leniency.", idiomatic: "I wish those who handle prisons to strive first for leniency." },
  { zh: "」----2三月，赦天下。", literal: "\" ----2 In the third month, he pardoned all under Heaven.", idiomatic: "\" ----2 In the third month he proclaimed a general amnesty." },
  { zh: "----3夏，大酺五日，民得酤酒。", literal: "----3 In summer, a great communal feast for five days; the people were permitted to sell wine.", idiomatic: "----3 In summer there was a great communal feast for five days and the people were permitted to sell wine." },
  { zh: "----4五月，丙戌，地震。", literal: "----4 In the fifth month, on bingxu, there was an earthquake.", idiomatic: "----4 In the fifth month, on the day bingxu, there was an earthquake." },
  { zh: "上庸地震二十二日。", literal: "Shangyong shook for twenty-two days.", idiomatic: "Shangyong shook for twenty-two days." },
  { zh: "壞城垣。", literal: "City walls were ruined.", idiomatic: "City walls were ruined." },
  { zh: "----5秋，七月，丙午，丞相舍免。", literal: "----5 In autumn, the seventh month, on bingwu, Chancellor She was dismissed.", idiomatic: "----5 In autumn, the seventh month, on the day bingwu, Chancellor She was dismissed." },
  { zh: "----6乙巳晦，日有食之。", literal: "----6 On the last day yisi, there was an eclipse of the sun.", idiomatic: "----6 On the last day yisi, the sun was eclipsed." },
  { zh: "----7八月，壬辰，以御史大夫衛綰為丞相，衛尉南陽直不疑為御史大夫。", literal: "----7 In the eighth month, on renchen, Grandee Secretary Wei Wan was made Chancellor and Commandant of the Guards Zhi Buyi of Nanyang was made Grandee Secretary.", idiomatic: "----7 In the eighth month, on the day renchen, Grandee Secretary Wei Wan was made chancellor and Commandant of the Guards Zhi Buyi of Nanyang was made grandee secretary." },
  { zh: "初，不疑為郎，同舍有告歸，誤持其同舍郎金去。", literal: "At the beginning, when Buyi was a palace gentleman, a man sharing quarters went home on leave and mistakenly took his fellow gentleman's gold away.", idiomatic: "Earlier, when Buyi was a palace gentleman, a man sharing his quarters went home on leave and mistakenly took his roommate's gold away." },
  { zh: "已而同舍郎覺亡，意不疑，不疑謝有之，買金償。", literal: "Afterward the fellow gentleman noticed the loss and suspected Buyi; Buyi apologized that he had done it and bought gold to repay.", idiomatic: "Later the roommate noticed the loss and suspected Buyi; Buyi apologized as if guilty and bought gold to repay him." },
  { zh: "後告歸者至而歸金，亡金郎大慚。", literal: "Later the man on leave returned and brought back the gold; the gentleman who had lost the gold was greatly ashamed.", idiomatic: "Later the man on leave returned and brought back the gold; the man who had lost it was deeply ashamed." },
  { zh: "以此稱為長者，稍遷至中大夫。", literal: "For this he was praised as an elder and was gradually promoted to Grand Master of the Palace.", idiomatic: "For this he was praised as a man of mature character and was gradually promoted to grand master of the palace." },
  { zh: "人或廷毀不疑，以為盜嫂，不疑聞，曰：「我乃無兄。", literal: "Someone slandered Buyi at court, saying he had stolen his sister-in-law; Buyi heard it and said: \"I in fact have no elder brother.", idiomatic: "Someone slandered Buyi at court, accusing him of carrying on with his sister-in-law; when Buyi heard it he said, \"I have no elder brother." },
  { zh: "」然終不自明也。", literal: "\" Yet in the end he never cleared himself.", idiomatic: "\" Yet in the end he never cleared himself." },
  { zh: "----8帝居禁中，召周亞夫賜食，獨置大胾，無切肉，又不置箸。", literal: "----8 The Emperor was in the inner palace, summoned Zhou Yafu to grant food, set out only a large chunk of meat with no sliced meat, and did not set out chopsticks.", idiomatic: "----8 The Emperor was in the inner palace, summoned Zhou Yafu to a meal, set out only a large chunk of meat with no sliced portions, and placed no chopsticks." },
  { zh: "亞夫心不平，顧謂尚席取箸。", literal: "Yafu's heart was not at peace; he turned and told the chief of tables to fetch chopsticks.", idiomatic: "Yafu was displeased and turned to tell the chief table attendant to fetch chopsticks." },
  { zh: "上視而笑曰：「此非不足君所乎！", literal: "The Emperor looked and laughed, saying: \"Is this not enough for you!", idiomatic: "The Emperor looked at him and laughed, saying, \"Is this not enough for you!" },
  { zh: "」亞夫免冠謝上，上曰：「起。", literal: "\" Yafu removed his cap and apologized to the Emperor; the Emperor said: \"Rise.", idiomatic: "\" Yafu removed his cap and apologized; the Emperor said, \"Rise." },
  { zh: "」亞夫因趨出。", literal: "\" Yafu thereupon hurried out.", idiomatic: "\" Yafu thereupon hurried out." },
  { zh: "上目送之曰：「此鞅鞅，非少主臣也。", literal: "The Emperor, seeing him off, said: \"This one is discontented—not a minister for a young lord.", idiomatic: "The Emperor watched him go and said, \"This one is discontented—not a minister for a young ruler." },
  { zh: "居無何，亞夫子為父買工官尚方甲楯五百被，可以葬者。", literal: "Before long, Yafu's son, for his father's burial, bought five hundred suits of armor and shields from the Works Office of the Imperial Workshop suitable for burial.", idiomatic: "Before long Yafu's son, for his father's burial, bought five hundred sets of armor and shields from the imperial workshop suitable for burial." },
  { zh: "取庸苦之，不與錢。", literal: "He hired laborers and tormented them, not giving money.", idiomatic: "He hired laborers and mistreated them, refusing to pay them." },
  { zh: "庸知其盜買縣官器，怨而上變，告子，事連污亞夫。", literal: "The laborers knew he had stolen and bought state office equipment; in resentment they reported by memorial, accusing the son, and the affair implicated and stained Yafu.", idiomatic: "The laborers knew he had illicitly bought state equipment; in resentment they filed a report accusing the son, and the affair implicated Yafu." },
  { zh: "書既聞，上下吏。", literal: "Once the memorial was known, the Emperor handed him down to the officials.", idiomatic: "Once the memorial was known the Emperor handed him over to the officials." },
  { zh: "吏簿責亞夫。", literal: "The officials interrogated Yafu from the register.", idiomatic: "The officials interrogated Yafu from the ledger." },
  { zh: "亞夫不對。", literal: "Yafu did not answer.", idiomatic: "Yafu made no reply." },
  { zh: "上罵之曰：「吾不用也！", literal: "The Emperor cursed him, saying: \"I have no use for you!", idiomatic: "The Emperor cursed him, saying, \"I have no use for you!" },
  { zh: "」召詣廷尉。", literal: "\" He summoned him to the Court Commandant.", idiomatic: "\" He summoned him to the Court Commandant." },
  { zh: "廷尉責問曰：「君侯欲反何？", literal: "The Court Commandant interrogated, saying: \"Marquis, why do you wish to rebel?", idiomatic: "The Court Commandant interrogated him, saying, \"Marquis, why do you wish to rebel?" },
  { zh: "」亞夫曰：「臣所買器，乃葬器也，何謂反乎？", literal: "\" Yafu said: \"The equipment your servant bought was burial equipment—what is called rebellion?", idiomatic: "\" Yafu said, \"What I bought was burial equipment—how is that called rebellion?" },
  { zh: "」吏曰：「君縱不欲反地上，即欲反地下耳！", literal: "\" The official said: \"My lord, even if you do not wish to rebel on earth, you wish to rebel underground!", idiomatic: "\" The official said, \"My lord, even if you do not wish to rebel on earth, you wish to rebel underground!" },
  { zh: "」吏侵之益急。", literal: "\" The officials pressed him ever more harshly.", idiomatic: "\" The officials pressed him ever more harshly." },
  { zh: "初，吏捕亞夫，亞夫欲自殺，其夫人止之，以故不得死，遂入廷尉，因不食五日，歐血而死。", literal: "At the beginning, when the officials seized Yafu, Yafu wished to kill himself; his wife stopped him, and for this reason he did not die; he then entered the Court Commandant's office and, for not eating five days, vomited blood and died.", idiomatic: "When the officials first seized Yafu he wished to kill himself; his wife stopped him, so he did not die then; he entered the Court Commandant's custody and, after five days without food, vomited blood and died." },
  { zh: "----9是歲，濟陰哀王不識薨。", literal: "----9 This year, Lamented King Bushi of Jiyin died.", idiomatic: "----9 That year Lamented King Bushi of Jiyin died." },
  { zh: "----1春，正月，地一日三動。", literal: "----1 In spring, the first month, the earth shook three times in one day.", idiomatic: "----1 In spring, the first month, the earth shook three times in one day." },
  { zh: "----2三月，匈奴入雁門，太守馮敬與戰，死。", literal: "----2 In the third month, the Xiongnu entered Yanmen; Administrator Feng Jing fought them and died.", idiomatic: "----2 In the third month the Xiongnu entered Yanmen; Administrator Feng Jing fought them and died." },
  { zh: "發車騎、材官屯雁門。", literal: "Chariots, cavalry, and materiel troops were dispatched to garrison Yanmen.", idiomatic: "Chariotry, cavalry, and materiel troops were dispatched to garrison Yanmen." },
  { zh: "----3春，以歲不登，禁內郡食馬粟；", literal: "----3 In spring, because the year did not yield a good harvest, the inner commanderies were forbidden to feed horses on grain;", idiomatic: "----3 In spring, because the harvest failed, the inner commanderies were forbidden to feed horses on grain;" },
  { zh: "沒入之。", literal: "what was used was confiscated.", idiomatic: "any grain so used was confiscated." },
  { zh: "----4夏，四月，詔曰：「雕文刻鏤，傷農事者也；", literal: "----4 In summer, the fourth month, an edict said: \"Carved patterns and cut inlay injure agricultural work;", idiomatic: "----4 In summer, the fourth month, an edict ran: \"Carved ornament and fine chasing injure farming;" },
  { zh: "錦繡纂組，害女工者也。", literal: "brocade, embroidery, and gathered weave harm women's work.", idiomatic: "brocade, embroidery, and fine weaving harm women's work." },
  { zh: "農事傷則饑之本，女工害則寒之原也。", literal: "When agricultural work is injured, that is the root of famine; when women's work is harmed, that is the source of cold.", idiomatic: "When farming is injured that is the root of famine; when women's work is harmed that is the source of cold." },
  { zh: "夫饑寒並至而能亡為非者寡矣。", literal: "When hunger and cold come together, those who can perish without doing wrong are few.", idiomatic: "When hunger and cold come together, few can avoid wrongdoing." },
  { zh: "朕親耕，後親桑，以奉宗廟粢盛、祭服，為天下先；", literal: "We personally plow; the empress personally tends mulberry, to supply the ancestral temple grain offerings and sacrificial robes, taking the lead for all under Heaven;", idiomatic: "We personally plow and the empress personally tends the mulberry, to supply the ancestral temple offerings and sacrificial robes, setting the example for the realm;" },
  { zh: "不受獻，減太官，省繇賦，欲天下務農蠶，素有蓄積，以備災害。", literal: "we do not accept tribute offerings, reduce the Grand Provisioner, and lighten corvée and taxes, wishing all under Heaven to devote themselves to farming and sericulture, always to have stores, and to prepare against disasters.", idiomatic: "we accept no tribute offerings, reduce the grand provisioner, and lighten corvée and taxes, wishing the realm to devote itself to farming and sericulture, always to keep stores, and to prepare against disaster." },
  { zh: "強毋攘弱，眾毋暴寡；", literal: "the strong must not seize from the weak; the many must not tyrannize the few;", idiomatic: "the strong must not seize from the weak; the many must not bully the few;" },
  { zh: "老耆以壽終，幼孤得遂長。", literal: "the aged complete their years; the young and orphaned are enabled to grow up.", idiomatic: "the aged may end their years in peace; the young and orphaned may grow up." },
  { zh: "今歲或不登，民食頗寡，其咎安在？", literal: "This year the harvest may not succeed; the people's food is rather scant—where does the fault lie?", idiomatic: "This year the harvest may fail and the people's food is scant—where does the fault lie?" },
  { zh: "或詐偽為吏，以貨賂為市，漁奪百姓，侵牟萬民。", literal: "Some falsely pose as officials, make bribery their market, fish and seize from the hundred surnames, and encroach upon and extort the myriad people.", idiomatic: "Some pose falsely as officials, trade in bribery, plunder the people, and prey upon the masses." },
  { zh: "縣丞，長吏也；", literal: "The county assistant is a chief official;", idiomatic: "The county assistant is a chief official;" },
  { zh: "奸法與盜盜，甚無謂也！", literal: "to twist the law and join with thieves in theft is very meaningless!", idiomatic: "to twist the law and join thieves in stealing is utterly senseless!" },
  { zh: "其令二千石各修其職；", literal: "Let the two-thousand-bushel officials each repair their duties;", idiomatic: "Let every two-thousand-bushel official attend to his duty;" },
  { zh: "不事官職、耗亂者，丞相以聞，請其罪。", literal: "those who do not attend to office duties and waste and disorder—let the Chancellor report and request their punishment.", idiomatic: "whoever neglects his office and causes waste and disorder—the chancellor is to report him and request punishment." },
  { zh: "佈告天下，使明知朕意。", literal: "Proclaim this to all under Heaven so that all clearly know Our intent.", idiomatic: "Proclaim this throughout the realm so that all may clearly know Our intent." },
  { zh: "」----5五月，詔貲算四得官。", literal: "\" ----5 In the fifth month, an edict: those whose property-tax assessment reached the fourth grade might obtain office.", idiomatic: "\" ----5 In the fifth month an edict ran: those whose property-tax assessment reached the fourth grade might obtain office." },
  { zh: "----6秋，大旱。", literal: "----6 In autumn, great drought.", idiomatic: "----6 In autumn there was great drought." },
  { zh: "----1冬，十月，日月皆食，赤五日。", literal: "----1 In winter, the tenth month, both sun and moon were eclipsed; [the sky] was red five days.", idiomatic: "----1 In winter, the tenth month, both sun and moon were eclipsed and the sky stayed red five days." },
  { zh: "----2十二月晦，雷；", literal: "----2 On the last day of the twelfth month, thunder;", idiomatic: "----2 On the last day of the twelfth month there was thunder;" },
  { zh: "日如紫；", literal: "the sun was like purple;", idiomatic: "the sun looked purple;" },
  { zh: "五星逆行守大微；", literal: "the five planets moved retrograde and guarded Great Supreme Palace;", idiomatic: "the five planets moved retrograde and guarded the Great Supreme Palace;" },
  { zh: "月貫天廷中。", literal: "the moon pierced through the Celestial Court.", idiomatic: "the moon pierced through the Celestial Court." },
  { zh: "----3春，正月，詔曰：「農，天下之本也。", literal: "----3 In spring, the first month, an edict said: \"Agriculture is the root of all under Heaven.", idiomatic: "----3 In spring, the first month, an edict ran: \"Agriculture is the root of all under Heaven." },
  { zh: "黃金、珠、玉，饑不可食，寒不可衣，以為幣用，不識其終始。", literal: "Gold, pearls, and jade—when hungry they cannot be eaten, when cold they cannot be worn; used as currency, one does not know their beginning and end.", idiomatic: "Gold, pearls, and jade cannot be eaten when hungry or worn when cold; used as currency, one cannot tell where they begin or end." },
  { zh: "間歲或不登，意為末者眾，農民寡也。", literal: "In some years the harvest fails; we suspect many pursue secondary trades and farmers are few.", idiomatic: "In some years the harvest fails; we suspect too many pursue secondary trades and too few remain farmers." },
  { zh: "其令郡國務勸農桑，益種樹，可得衣食物。", literal: "Let commanderies and kingdoms earnestly encourage farming and sericulture, increase planting of trees, and obtain clothing and food.", idiomatic: "Let commanderies and kingdoms earnestly encourage farming and sericulture, plant more trees, and secure clothing and food." },
  { zh: "吏發民若取庸采黃金、珠、玉者，坐贓為盜。", literal: "Officials who mobilize the people yet take payment to gather gold, pearls, and jade are convicted of embezzlement as thieves.", idiomatic: "Officials who mobilize the people yet take fees to gather gold, pearls, and jade shall be convicted of embezzlement as thieves." },
  { zh: "二千石聽者，與同罪。", literal: "Grand administrators who heed it share the same crime.", idiomatic: "Grand administrators who allow it share the same crime." },
  { zh: "」----4甲寅，皇太子冠。", literal: "\" ----4 On jiayin, the crown prince received the capping.", idiomatic: "\" ----4 On jiayin the crown prince received the capping." },
  { zh: "----5甲子，帝崩於未央宮。", literal: "----5 On jiazi, the Emperor died in Weiyang Palace.", idiomatic: "----5 On jiazi the Emperor died in Weiyang Palace." },
  { zh: "太子即皇帝位，年十六。", literal: "The crown prince assumed the imperial throne; he was sixteen.", idiomatic: "The crown prince took the throne; he was sixteen." },
  { zh: "尊皇太后為太皇太后，皇后為皇太后。", literal: "The empress dowager was honored as grand empress dowager and the empress as empress dowager.", idiomatic: "The empress dowager was honored as grand empress dowager and the empress as empress dowager." },
  { zh: "----6二月，癸酉，葬孝景皇帝於陽陵。", literal: "----6 In the second month, on guiyou, Emperor Xiaojing was buried at Yangling.", idiomatic: "----6 In the second month, on guiyou, Emperor Xiaojing was buried at Yangling." },
  { zh: "三月，封皇太后同母弟田蚡為武安侯，勝為周陽侯。", literal: "In the third month, the empress dowager's younger brother by the same mother Tian Fen was enfeoffed as Marquis of Wu'an and Sheng as Marquis of Zhouyang.", idiomatic: "In the third month the empress dowager's uterine younger brothers Tian Fen and Sheng were enfeoffed as marquises of Wu'an and Zhouyang." },
  { zh: "::班固贊曰：孔子稱：「斯民也，三代之所以直道而行也。", literal: ":: Ban Gu's praise says: Confucius said: \"It is this people for whom the Three Dynasties walked the straight Way.", idiomatic: ":: Ban Gu's praise says: Confucius said, \"It is this people for whom the Three Dynasties walked the straight Way." },
  { zh: "」信哉！", literal: "\" How true!", idiomatic: "\" How true!" },
  { zh: "周、秦之敝，罔密文峻，而奸軌不勝，漢興，掃除煩苛，與民休息；", literal: "The failings of Zhou and Qin were nets dense and statutes severe, yet wicked paths could not be overcome; when Han arose it swept away vexatious harshness and rested the people;", idiomatic: "Zhou and Qin failed through dense nets and severe statutes, yet wicked ways could not be overcome; when Han arose it swept away vexatious harshness and let the people rest;" },
  { zh: "至於孝文，加這以恭儉；", literal: "As for Emperor Wen, upon this he added reverence and thrift;", idiomatic: "Under Emperor Wen reverence and thrift were added upon this;" },
  { zh: "孝景遵業。", literal: "Emperor Jing followed his enterprise.", idiomatic: "Emperor Jing followed his course." },
  { zh: "五六十載之間，至於移風易俗，黎民醇厚。", literal: "Within fifty or sixty years, customs were transformed and the common people grew pure and thick.", idiomatic: "Within fifty or sixty years customs were transformed and the common people grew pure and steadfast." },
  { zh: "周雲成、康，漢言文、景，美矣！", literal: "Zhou spoke of Cheng and Kang; Han spoke of Wen and Jing—how beautiful!", idiomatic: "Zhou spoke of Cheng and Kang; Han spoke of Wen and Jing—how fine!" },
  { zh: "::漢興，接秦之弊，作業劇而財匱，自天子不能具鈞駟，而將相或乘牛車，齊民無藏蓋。", literal: ":: When Han arose it took over Qin's failings; labor was intense and wealth depleted—even the Son of Heaven could not assemble a matched team of four, while generals and chancellors sometimes rode ox-carts, and the common people had nothing stored.", idiomatic: ":: When Han arose it inherited Qin's ruin; labor was intense and wealth depleted—even the Son of Heaven could not assemble a matched four-horse team, while generals and chancellors sometimes rode ox-carts and commoners had nothing stored." },
  { zh: "天下已平，高祖乃令賈人不得衣絲、乘車，重租稅以困辱之。", literal: "When all under Heaven was settled, Gaozu then ordered merchants not to wear silk or ride carriages, and imposed heavy rents and taxes to distress and humiliate them.", idiomatic: "Once the realm was settled, Gaozu ordered merchants not to wear silk or ride carriages and imposed heavy rents and taxes to distress and humiliate them." },
  { zh: "孝惠、高後時，為天下初定，復馳商賈之律；", literal: "In the times of Emperor Hui and Empress Gao, because the realm was newly settled, the laws restraining merchants were relaxed again;", idiomatic: "Under Emperor Hui and Empress Gao, because the realm was newly settled, the laws restraining merchants were relaxed again;" },
  { zh: "然市井之子孫，亦不得仕宦為吏。", literal: "yet descendants of market folk still could not enter office and serve as officials.", idiomatic: "yet descendants of market folk still could not enter office as officials." },
  { zh: "量吏祿，度官用，以賦於民。", literal: "Official salaries were measured and government expenses estimated, then levied upon the people.", idiomatic: "Official salaries were measured and government expenses estimated, then levied upon the people." },
  { zh: "而山川、園池、市井租稅之入，自天子以至於封君湯沐邑，皆各為私奉養焉，不領於天下之經費。", literal: "Yet revenue from mountains and rivers, parks and ponds, and market rents—from the Son of Heaven down to enfeoffed lords' bath towns—each served private maintenance and did not enter the realm's regular expenses.", idiomatic: "Yet revenue from mountains, rivers, parks, ponds, and market rents—from the Son of Heaven down to enfeoffed lords' bath towns—each served private maintenance and did not enter the realm's regular budget." },
  { zh: "漕轉山東粟以給中都官，歲不過數十萬石。", literal: "Grain from east of the mountains was transported by water to supply the capital officials; each year it did not exceed several hundred thousand piculs.", idiomatic: "Grain from east of the mountains was shipped to supply the capital officials; each year it did not exceed several hundred thousand piculs." },
  { zh: "繼以孝文、孝景，清淨恭儉，安養天下，七十餘年之間，國家無事，非遇水旱之災，民則人給家足。", literal: "Succeeding them, Emperors Wen and Jing were pure, reverent, and thrifty, peacefully nurturing all under Heaven; for more than seventy years the state had no troubles, and unless water or drought struck, the people had enough for each person and each household.", idiomatic: "Under Emperors Wen and Jing, pure, reverent, and thrifty, the realm was peacefully nurtured; for more than seventy years the state had no troubles, and unless flood or drought struck, each person and household had enough." },
  { zh: "都鄙廩庾皆滿，而府庫餘貨財；", literal: "Granaries in capital and countryside were all full, and the treasuries had surplus goods and wealth;", idiomatic: "Granaries in capital and countryside were full, and the treasuries held surplus goods and wealth;" },
  { zh: "京師之錢累巨萬，貫朽而不可校；", literal: "cash in the capital piled in tens of thousands; strings rotted and could not be counted;", idiomatic: "cash in the capital piled in the tens of thousands; strings rotted and could not be counted;" },
  { zh: "太倉之粟陳陳相因，充溢露積於外，至腐敗不可食。", literal: "grain in the Grand Granary lay layer upon layer, overflowing and piled in the open until it rotted and could not be eaten.", idiomatic: "grain in the Grand Granary lay layer upon layer, overflowing and piled in the open until it rotted and could not be eaten." },
  { zh: "眾庶街巷有馬，而阡陌之間成群，乘字牝者擯而不得聚會。", literal: "Among the multitude, lanes and alleys had horses, and between field paths they gathered in herds; those riding mares with foals at foot were barred and could not join gatherings.", idiomatic: "Among the common people lanes and alleys had horses and field paths teemed with herds; riders of mares with foals at foot were barred from gatherings." },
  { zh: "守閭閻者食粱肉，為吏者長子孫，居官者以為姓號。", literal: "Gatekeepers of neighborhood wards ate fine grain and meat; those serving as officials raised sons and grandsons; those in office took it as surname and title.", idiomatic: "Neighborhood gatekeepers ate fine grain and meat; officials raised sons and grandsons; office became family name and title." },
  { zh: "故人人自愛而重犯法，先行義而後絀辱焉。", literal: "Therefore each person cherished himself and held the law in weight, putting righteousness first and punishment and disgrace after.", idiomatic: "Therefore each person cherished himself and held the law dear, putting righteousness first and punishment and disgrace after." },
  { zh: "當此之時，罔疏而民富，役財驕溢，或至兼併；", literal: "At this time nets were loose and the people rich; wielding wealth with arrogant excess, some even reached merger and absorption;", idiomatic: "At this time laws were loose and the people rich; wielding wealth with arrogant excess, some even absorbed their neighbors;" },
  { zh: "豪黨之徒，以武斷於鄉曲。", literal: "men of powerful factions adjudicated by force in villages and hamlets.", idiomatic: "powerful factions adjudicated by force in villages and hamlets." },
  { zh: "宗室有土，公、卿、大夫以下，爭於奢侈，室廬、輿服僭於上，無限度。", literal: "Imperial clansmen held fiefs; from dukes, ministers, and grand masters downward they strove in luxury—dwellings, carriages, and dress exceeding their superiors without limit.", idiomatic: "Imperial clansmen held fiefs; from dukes, ministers, and grand masters downward they strove in luxury—dwellings, carriages, and dress exceeding their superiors without limit." },
  { zh: "物盛而衰，固其變也。", literal: "When things flourish they decline—such change is fixed.", idiomatic: "When things flourish they decline—such change is fixed." },
  { zh: "自是之後，孝武內窮侈靡，外攘夷狄，天下蕭然，財力耗矣！", literal: "From this onward, Emperor Wu internally exhausted himself in extravagance and externally campaigned against the Yi and Di; all under Heaven grew desolate and financial strength was spent!", idiomatic: "From then on Emperor Wu internally exhausted the realm in extravagance and externally campaigned against the barbarians; the realm grew desolate and its wealth was spent!" },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
